/* 10వ తరగతి – phy పూర్తి పాఠాలు (tools/split/split_class10.py) */
((window.RAAY_TBF=window.RAAY_TBF||{})[10]=window.RAAY_TBF[10]||{})["phy"]=[{"id":"ph1","no":1,"t":"రసాయన చర్యలు, సమీకరణాలు (Chemical Reactions and Equations)","m":[6],"ty":"Chapter 1","th":"రసాయన సమీకరణాలు, తుల్యం చేయడం, చర్యల రకాలు, ఆక్సీకరణ–క్షయకరణం, క్షయం, ముక్కిపోవడం","sum":"పాలు పెరుగవడం, ఇనుము తుప్పు పట్టడం, ఆహారం జీర్ణం కావడం – ఇవన్నీ రసాయన చర్యలు. స్థితి మార్పు, రంగు మార్పు, వాయువు విడుదల, ఉష్ణోగ్రత మార్పు చర్య జరిగిందని చెప్పే గుర్తులు. చర్యను క్లుప్తంగా రాసేది రసాయన సమీకరణం; ద్రవ్యరాశి నిత్యత్వ నియమం ప్రకారం రెండు వైపులా ప్రతి మూలకం పరమాణువుల సంఖ్య సమానం కావాలి – అదే తుల్యమైన (balanced) సమీకరణం. స్థితి గుర్తులు (s), (l), (g), (aq). చర్యల రకాలు: సంయోగం (combination), వియోగం (decomposition – ఉష్ణం, కాంతి, విద్యుత్), స్థానభ్రంశం (displacement), ద్వంద్వ స్థానభ్రంశం (double displacement – అవక్షేపణం), ఆక్సీకరణ–క్షయకరణం (redox). ఉష్ణాన్ని విడుదల చేసేవి ఉష్ణమోచక (exothermic), గ్రహించేవి ఉష్ణగ్రాహక (endothermic). దైనందిన జీవితంలో ఆక్సీకరణ ఫలితాలు: క్షయం (corrosion – తుప్పు), ముక్కిపోవడం (rancidity).","pts":["రసాయన చర్యకు గుర్తులు: స్థితి మార్పు, రంగు మార్పు, వాయువు విడుదల, ఉష్ణోగ్రత మార్పు.","పద సమీకరణం: మెగ్నీషియం + ఆక్సిజన్ → మెగ్నీషియం ఆక్సైడ్; రసాయన సమీకరణం: 2Mg + O₂ → 2MgO.","తుల్యం చేయడం: ద్రవ్యరాశి నిత్యత్వ నియమం – ఫార్ములాలు మార్చకుండా గుణకాలు మాత్రమే మార్చాలి (3Fe + 4H₂O → Fe₃O₄ + 4H₂).","సంయోగ చర్య: A + B → AB (CaO + H₂O → Ca(OH)₂ – సున్నం తేలిక, ఉష్ణమోచకం).","వియోగ చర్య: AB → A + B; ఉష్ణ (CaCO₃ → CaO + CO₂), కాంతి (2AgCl → 2Ag + Cl₂), విద్యుత్ (2H₂O → 2H₂ + O₂).","స్థానభ్రంశం: ఎక్కువ చర్యాశీల లోహం తక్కువ దానిని తొలగిస్తుంది (Fe + CuSO₄ → FeSO₄ + Cu – నీలం రంగు పోతుంది).","ద్వంద్వ స్థానభ్రంశం: అయాన్ల మార్పిడి; అవక్షేపం ఏర్పడితే అవక్షేపణ చర్య (Na₂SO₄ + BaCl₂ → BaSO₄↓ + 2NaCl).","ఆక్సీకరణం: ఆక్సిజన్ గ్రహించడం / హైడ్రోజన్ కోల్పోవడం; క్షయకరణం: ఆక్సిజన్ కోల్పోవడం / హైడ్రోజన్ గ్రహించడం (CuO + H₂ → Cu + H₂O).","క్షయం (corrosion): ఇనుము తుప్పు, వెండి నల్లబడటం, రాగి పచ్చబడటం; పెయింట్, గ్రీజు, గాల్వనైజింగ్ తో నివారణ.","ముక్కిపోవడం (rancidity): నూనెలు, కొవ్వుల ఆక్సీకరణ – వాసన, రుచి మార్పు; యాంటీఆక్సిడెంట్లు, నైట్రోజన్ నింపడం, గాలి చొరని డబ్బాలతో నివారణ."],"w":[["రసాయన చర్య","Chemical reaction"],["చర్యాజనకాలు","Reactants"],["క్రియాజన్యాలు","Products"],["తుల్య సమీకరణం","Balanced equation"],["సంయోగ చర్య","Combination reaction"],["వియోగ చర్య","Decomposition reaction"],["స్థానభ్రంశ చర్య","Displacement reaction"],["ద్వంద్వ స్థానభ్రంశం","Double displacement"],["అవక్షేపం","Precipitate"],["ఆక్సీకరణం / క్షయకరణం","Oxidation / Reduction"],["ఉష్ణమోచక / ఉష్ణగ్రాహక","Exothermic / Endothermic"],["క్షయం / ముక్కిపోవడం","Corrosion / Rancidity"]],"gr":{"t":"ముఖ్య సమీకరణాలు","p":["2Mg + O₂ → 2MgO (తెల్లని ప్రకాశవంతమైన మంట)","Zn + H₂SO₄ → ZnSO₄ + H₂↑","Pb(NO₃)₂ + 2KI → PbI₂↓ (పసుపు) + 2KNO₃","CaO + H₂O → Ca(OH)₂ + ఉష్ణం","C₆H₁₂O₆ + 6O₂ → 6CO₂ + 6H₂O + శక్తి (శ్వాసక్రియ – ఉష్ణమోచకం)","2FeSO₄ → Fe₂O₃ + SO₂ + SO₃ (ఆకుపచ్చ స్ఫటికాలు వేడి చేస్తే)"]},"qa":[["మెగ్నీషియం రిబ్బన్‌ను మండించే ముందు ఎందుకు శుభ్రం చేయాలి?","దానిపై ఉన్న MgO పొరను తొలగించడానికి – లేకపోతే సులభంగా మండదు."],["తెల్లవేయడానికి వాడే పదార్థం X?","కాల్షియం ఆక్సైడ్ (CaO); CaO + H₂O → Ca(OH)₂."],["నీటి విద్యుద్విశ్లేషణలో ఒక పరీక్షనాళికలో వాయువు రెట్టింపు ఎందుకు?","2H₂O → 2H₂ + O₂ – హైడ్రోజన్, ఆక్సిజన్ ఘనపరిమాణ నిష్పత్తి 2 : 1; ఎక్కువ వాయువు హైడ్రోజన్."],["CuSO₄ ద్రావణంలో ఇనుప మేకు వేస్తే రంగు ఎందుకు మారుతుంది?","Fe, Cu ను స్థానభ్రంశం చేసి FeSO₄ (లేత ఆకుపచ్చ) ఏర్పడుతుంది."],["CuO + H₂ → Cu + H₂O లో ఆక్సీకరణం చెందేది?","H₂ ఆక్సీకరణం, CuO క్షయకరణం."],["శ్వాసక్రియ ఉష్ణమోచక చర్య ఎందుకు?","గ్లూకోజ్ ఆక్సీకరణంలో శక్తి విడుదల అవుతుంది."]],"act":"సున్నం (CaO) కొద్దిగా బీకరులో తీసుకుని నెమ్మదిగా నీరు పోసి బీకరును తాకండి – వేడెక్కుతుంది (సంయోగ, ఉష్ణమోచక చర్య). ఇనుప మేకును CuSO₄ ద్రావణంలో 20 నిమిషాలు ఉంచి రంగు మార్పు గమనించండి.","kn":"ఫోటోగ్రఫీ (పాత ఫిల్మ్ కెమెరాలు) లో AgBr కాంతితో వియోగం చెంది వెండిగా మారడమే బొమ్మకు కారణం. ఆహార పొట్లాల్లో (చిప్స్) నైట్రోజన్ నింపేది ముక్కిపోకుండా ఉండటానికే.","qz":[["రసాయన చర్యకు గుర్తు కానిది?","ఆకారం మారడం మాత్రమే","రంగు మార్పు","వాయువు విడుదల","ఉష్ణోగ్రత మార్పు"],["సమీకరణాన్ని తుల్యం చేయడానికి ఆధారం?","ద్రవ్యరాశి నిత్యత్వ నియమం","స్థిర అనుపాత నియమం","బాయిల్ నియమం","ఓమ్ నియమం"],["CaO + H₂O → Ca(OH)₂ ఏ చర్య?","సంయోగం","వియోగం","స్థానభ్రంశం","ద్వంద్వ స్థానభ్రంశం"],["CaCO₃ → CaO + CO₂ ఏ చర్య?","ఉష్ణ వియోగం","కాంతి వియోగం","సంయోగం","స్థానభ్రంశం"],["Fe + CuSO₄ → FeSO₄ + Cu ఏ చర్య?","స్థానభ్రంశం","ద్వంద్వ స్థానభ్రంశం","సంయోగం","వియోగం"],["Na₂SO₄ + BaCl₂ → BaSO₄ + 2NaCl లో తెల్లని అవక్షేపం?","BaSO₄","NaCl","BaCl₂","Na₂SO₄"],["Pb(NO₃)₂ + KI అవక్షేపం రంగు?","పసుపు","తెలుపు","నీలం","నలుపు"],["ఆక్సీకరణం అంటే?","ఆక్సిజన్ గ్రహించడం","ఆక్సిజన్ కోల్పోవడం","హైడ్రోజన్ గ్రహించడం","ఎలక్ట్రాన్లు గ్రహించడం"],["2PbO + C → 2Pb + CO₂ లో క్షయకరణం చెందేది?","PbO","C","CO₂","Pb"],["నీటి విద్యుద్విశ్లేషణలో H₂ : O₂ ఘనపరిమాణం?","2 : 1","1 : 2","1 : 1","8 : 1"],["AgCl సూర్యకాంతిలో ఏ రంగుకు మారుతుంది?","బూడిద (grey)","పసుపు","నీలం","ఆకుపచ్చ"],["శ్వాసక్రియ ఏ రకం చర్య?","ఉష్ణమోచకం","ఉష్ణగ్రాహకం","వియోగం","స్థానభ్రంశం"],["చిప్స్ పొట్లాల్లో నింపే వాయువు?","నైట్రోజన్","ఆక్సిజన్","హైడ్రోజన్","CO₂"],["రాగి గాలిలో వేడి చేస్తే ఏర్పడే నల్లని పదార్థం?","CuO","Cu₂O","CuSO₄","CuCO₃"],["(aq) గుర్తు అర్థం?","నీటి ద్రావణం","ఘనం","ద్రవం","వాయువు"],["Fe₂O₃ + 2Al → Al₂O₃ + 2Fe ఏ చర్య?","స్థానభ్రంశం","సంయోగం","వియోగం","ద్వంద్వ స్థానభ్రంశం"],["తుప్పు రసాయన నామం?","Fe₂O₃·xH₂O (జలయుత ఫెర్రిక్ ఆక్సైడ్)","FeO","Fe₃O₄","FeSO₄"],["ఆకుపచ్చ FeSO₄ స్ఫటికాలు వేడి చేస్తే వచ్చే వాసన?","మండే సల్ఫర్ వాసన (SO₂)","అమ్మోనియా","కుళ్ళిన గుడ్డు","వాసన లేదు"]],"wb":{"mis":"సమీకరణం తుల్యం చేసేటప్పుడు ఫార్ములాల్లోని సూచికలు (H₂O → H₂O₂) మార్చడం తప్పు – ముందు గుణకాలు మాత్రమే. ఆక్సీకరణం, క్షయకరణం ఎప్పుడూ కలిసే జరుగుతాయి (redox). \"CO₂ ఆక్సీకరణం చెందింది\" వంటి వాక్యాలు చూడండి – CO₂ క్రియాజన్యం, చర్యాజనకం కాదు.","qz":[["2PbO + C → 2Pb + CO₂ – తప్పు వాక్యాలు?","(a) మరియు (b)","(a) మరియు (c)","(a), (b), (c)","అన్నీ"],["ఇనుప రజనుకు సజల HCl కలిపితే?","హైడ్రోజన్, ఐరన్ క్లోరైడ్","క్లోరిన్, ఐరన్ హైడ్రాక్సైడ్","చర్య జరగదు","ఐరన్ లవణం, నీరు"],["H₂ + N₂ → NH₃ తుల్యం?","3H₂ + N₂ → 2NH₃","H₂ + N₂ → 2NH₃","3H₂ + 2N₂ → 2NH₃","H₂ + 3N₂ → NH₃"],["NaOH + H₂SO₄ తుల్యం?","2NaOH + H₂SO₄ → Na₂SO₄ + 2H₂O","NaOH + H₂SO₄ → Na₂SO₄ + H₂O","NaOH + 2H₂SO₄ → Na₂SO₄ + H₂O","2NaOH + 2H₂SO₄ → Na₂SO₄ + 2H₂O"],["ZnCO₃ → ZnO + CO₂ ఏ రకం?","వియోగం","సంయోగం","స్థానభ్రంశం","ద్వంద్వ స్థానభ్రంశం"],["వెండి శుద్ధిలో AgNO₃ నుండి Ag ను తొలగించే లోహం?","Cu","Zn","Fe","Al"],["ఇనుప వస్తువులకు పెయింట్ ఎందుకు?","తుప్పు పట్టకుండా","మెరుపు కోసం","బరువు పెంచడానికి","విద్యుత్ కోసం"],["మెరిసే గోధుమ రంగు మూలకం X వేడి చేస్తే నల్లగా మారింది. X?","రాగి (Cu)","ఇనుము","వెండి","బంగారం"],["2AgBr → 2Ag + Br₂ కి కావలసిన శక్తి?","కాంతి","ఉష్ణం","విద్యుత్","శబ్దం"],["అవక్షేపణ చర్య ఏ రకం?","ద్వంద్వ స్థానభ్రంశం","సంయోగం","వియోగం","ఉష్ణ వియోగం"]],"pg":"6–37","f":"books/10/Class10_Physical_Science_Textbook.pdf","p":12,"lb":"పాఠ్యపుస్తకం","ws":["పాఠంలోని ప్రశ్నలు 1 (పుట 16) – 3 ప్రశ్నలు","పాఠంలోని ప్రశ్నలు 2 (పుట 24) – 2 ప్రశ్నలు","పాఠంలోని ప్రశ్నలు 3 (పుట 30) – 3 ప్రశ్నలు","అభ్యాసాలు – Exercises (పుట 32) – 20 ప్రశ్నలు"]},"tg":[["పాఠంలోని ప్రశ్నలు 1 (పుట 16)",["1) మెగ్నీషియం రిబ్బన్‌పై గాలితో చర్య వల్ల MgO పొర ఏర్పడుతుంది. ఆ పొర మండటాన్ని అడ్డుకుంటుంది, కాబట్టి ఇసుక కాగితంతో శుభ్రం చేసి మండించాలి","2) (i) H₂ + Cl₂ → 2HCl (ii) 3BaCl₂ + Al₂(SO₄)₃ → 3BaSO₄ + 2AlCl₃ (iii) 2Na + 2H₂O → 2NaOH + H₂","3) (i) BaCl₂(aq) + Na₂SO₄(aq) → BaSO₄(s) + 2NaCl(aq) (ii) NaOH(aq) + HCl(aq) → NaCl(aq) + H₂O(l)"]],["పాఠంలోని ప్రశ్నలు 2 (పుట 24)",["1) (i) X = కాల్షియం ఆక్సైడ్ (సున్నం, quick lime) – CaO (ii) CaO(s) + H₂O(l) → Ca(OH)₂(aq) + ఉష్ణం (తేలిన సున్నం)","2) నీటి విద్యుద్విశ్లేషణ: 2H₂O → 2H₂ + O₂. ఒక అణువు ఆక్సిజన్‌కు రెండు అణువుల హైడ్రోజన్ వస్తుంది, కాబట్టి ఘనపరిమాణం రెట్టింపు. ఆ వాయువు హైడ్రోజన్"]],["పాఠంలోని ప్రశ్నలు 3 (పుట 30)",["1) ఇనుము రాగి కంటే ఎక్కువ చర్యాశీలం – Fe + CuSO₄ → FeSO₄ + Cu. నీలి CuSO₄ బదులు లేత ఆకుపచ్చ FeSO₄ ఏర్పడుతుంది, మేకుపై గోధుమ రాగి పూత","2) Pb(NO₃)₂(aq) + 2KI(aq) → PbI₂(s) (పసుపు అవక్షేపం) + 2KNO₃(aq); లేదా AgNO₃ + NaCl → AgCl↓ + NaNO₃","3) (i) Na ఆక్సీకరణం, O₂ క్షయకరణం (ii) H₂ ఆక్సీకరణం (H₂O గా), CuO క్షయకరణం (Cu గా)"]],["అభ్యాసాలు – Exercises (పుట 32)",["1) (i) (a) మరియు (b) తప్పు – క్షయకరణం చెందేది PbO (లెడ్ ఆక్సైడ్), ఆక్సీకరణం చెందేది C; CO₂ క్రియాజన్యం","2) (d) స్థానభ్రంశ చర్య – Al, Fe ను Fe₂O₃ నుండి తొలగిస్తుంది (థర్మిట్ చర్య)","3) (a) హైడ్రోజన్ వాయువు, ఐరన్ క్లోరైడ్ – Fe + 2HCl → FeCl₂ + H₂","4) రెండు వైపులా ప్రతి మూలకం పరమాణువుల సంఖ్య సమానంగా ఉండే సమీకరణం తుల్య సమీకరణం. రసాయన చర్యలో ద్రవ్యరాశి సృష్టించబడదు, నశించదు (ద్రవ్యరాశి నిత్యత్వ నియమం) – అందుకే తుల్యం చేయాలి","5) (a) 3H₂(g) + N₂(g) → 2NH₃(g) (b) 2H₂S(g) + 3O₂(g) → 2H₂O(l) + 2SO₂(g) (c) 3BaCl₂(aq) + Al₂(SO₄)₃(aq) → 2AlCl₃(aq) + 3BaSO₄(s) (d) 2K(s) + 2H₂O(l) → 2KOH(aq) + H₂(g)","6) (a) 2HNO₃ + Ca(OH)₂ → Ca(NO₃)₂ + 2H₂O (b) 2NaOH + H₂SO₄ → Na₂SO₄ + 2H₂O (c) NaCl + AgNO₃ → AgCl + NaNO₃ (ముందే తుల్యం) (d) BaCl₂ + H₂SO₄ → BaSO₄ + 2HCl","7) (a) Ca(OH)₂ + CO₂ → CaCO₃ + H₂O (b) Zn + 2AgNO₃ → Zn(NO₃)₂ + 2Ag (c) 2Al + 3CuCl₂ → 2AlCl₃ + 3Cu (d) BaCl₂ + K₂SO₄ → BaSO₄ + 2KCl","8) (a) 2KBr(aq) + BaI₂(aq) → 2KI(aq) + BaBr₂(s) – ద్వంద్వ స్థానభ్రంశం (b) ZnCO₃(s) → ZnO(s) + CO₂(g) – వియోగం (c) H₂(g) + Cl₂(g) → 2HCl(g) – సంయోగం (d) Mg(s) + 2HCl(aq) → MgCl₂(aq) + H₂(g) – స్థానభ్రంశం","9) ఉష్ణం విడుదలయ్యే చర్యలు ఉష్ణమోచకం: C + O₂ → CO₂ + ఉష్ణం; CaO + H₂O → Ca(OH)₂ + ఉష్ణం. ఉష్ణం గ్రహించే చర్యలు ఉష్ణగ్రాహకం: CaCO₃ + ఉష్ణం → CaO + CO₂; 2AgCl → 2Ag + Cl₂ (కాంతి శక్తి)","10) శ్వాసక్రియలో గ్లూకోజ్ ఆక్సిజన్‌తో ఆక్సీకరణం చెంది శక్తి విడుదల అవుతుంది: C₆H₁₂O₆ + 6O₂ → 6CO₂ + 6H₂O + శక్తి – అందుకే ఉష్ణమోచకం","11) సంయోగంలో రెండు/అంతకంటే ఎక్కువ పదార్థాలు కలిసి ఒకటి ఏర్పడుతుంది; వియోగంలో ఒకే పదార్థం విడిపోయి అనేకం ఏర్పడతాయి – వ్యతిరేకం. సంయోగం: CaO + CO₂ → CaCO₃; 2H₂ + O₂ → 2H₂O. వియోగం: CaCO₃ → CaO + CO₂; 2H₂O → 2H₂ + O₂","12) ఉష్ణం: CaCO₃ → CaO + CO₂ (లేదా 2Pb(NO₃)₂ → 2PbO + 4NO₂ + O₂). కాంతి: 2AgBr → 2Ag + Br₂. విద్యుత్: 2H₂O → 2H₂ + O₂","13) స్థానభ్రంశంలో ఎక్కువ చర్యాశీల మూలకం తక్కువ చర్యాశీల మూలకాన్ని దాని సమ్మేళనం నుండి తొలగిస్తుంది: Zn + CuSO₄ → ZnSO₄ + Cu. ద్వంద్వ స్థానభ్రంశంలో రెండు సమ్మేళనాల మధ్య అయాన్ల మార్పిడి: Na₂SO₄ + BaCl₂ → BaSO₄ + 2NaCl","14) Cu(s) + 2AgNO₃(aq) → Cu(NO₃)₂(aq) + 2Ag(s)","15) కరగని ఘన పదార్థం (అవక్షేపం) ఏర్పడే చర్య అవక్షేపణ చర్య. ఉదా: Na₂SO₄ + BaCl₂ → BaSO₄↓ (తెలుపు) + 2NaCl; Pb(NO₃)₂ + 2KI → PbI₂↓ (పసుపు) + 2KNO₃","16) (a) ఆక్సీకరణం = ఆక్సిజన్ గ్రహించడం: 2Cu + O₂ → 2CuO; C + O₂ → CO₂ (b) క్షయకరణం = ఆక్సిజన్ కోల్పోవడం: CuO + H₂ → Cu + H₂O; ZnO + C → Zn + CO","17) X = రాగి (Cu); నల్లని పదార్థం = కాపర్ ఆక్సైడ్ (CuO): 2Cu + O₂ → 2CuO","18) పెయింట్ ఇనుముకు గాలి, తేమ తగలకుండా అడ్డుకుంటుంది – తుప్పు (క్షయం) పట్టదు","19) నైట్రోజన్ జడ వాయువు; ఆక్సిజన్‌ను తొలగించి నూనె, కొవ్వుల ఆక్సీకరణం (ముక్కిపోవడం) జరగకుండా చేస్తుంది","20) (a) క్షయం: లోహం చుట్టూ ఉన్న తేమ, ఆమ్లాలు, వాయువులతో చర్య జరిపి క్షీణించడం – ఉదా: ఇనుము తుప్పు (Fe₂O₃·xH₂O), వెండి నల్లబడటం (b) ముక్కిపోవడం: నూనెలు, కొవ్వులు ఆక్సీకరణం చెంది వాసన, రుచి మారడం – ఉదా: ఎక్కువ రోజుల నిల్వ చిప్స్"]]],"by":"భౌతిక శాస్త్రం 10వ తరగతి (పుటలు 6–37)"},{"id":"ph2","no":2,"t":"ఆమ్లాలు, క్షారాలు, లవణాలు (Acids, Bases and Salts)","m":[7],"ty":"Chapter 2","th":"సూచికలు, ఆమ్ల–క్షార ధర్మాలు, తటస్థీకరణం, pH స్కేలు, నిత్య జీవిత లవణాలు","sum":"ఆమ్లాలు పుల్లగా ఉండి నీలి లిట్మస్‌ను ఎరుపుగా, క్షారాలు చేదుగా ఉండి ఎరుపు లిట్మస్‌ను నీలంగా మారుస్తాయి. సహజ సూచికలు (లిట్మస్, పసుపు, ఎర్ర క్యాబేజీ), సంశ్లేషిత సూచికలు (మిథైల్ ఆరెంజ్, ఫినాఫ్తలీన్), వాసన సూచికలు (ఉల్లి, వెనిల్లా, లవంగ నూనె). ఆమ్లం + లోహం → లవణం + H₂; ఆమ్లం + లోహ కార్బొనేట్/హైడ్రోజన్ కార్బొనేట్ → లవణం + CO₂ + నీరు; ఆమ్లం + క్షారం → లవణం + నీరు (తటస్థీకరణం). నీటిలో ఆమ్లాలు H⁺ (H₃O⁺), క్షారాలు OH⁻ అయాన్లు ఇస్తాయి – నీరు లేకుండా ఆమ్ల ధర్మం కనిపించదు. pH స్కేలు 0–14: 7 తటస్థం, 7 కంటే తక్కువ ఆమ్లం, ఎక్కువ క్షారం. మన శరీరం (7.0–7.8), జీర్ణక్రియ, దంతక్షయం (pH 5.5 కంటే తక్కువ), మొక్కల నేల, తేనెటీగ కాటు వంటి వాటిలో pH ముఖ్యం. సాధారణ ఉప్పు నుండి NaOH (క్లోర్–ఆల్కలీ), బ్లీచింగ్ పౌడర్, బేకింగ్ సోడా, వాషింగ్ సోడా తయారవుతాయి; ప్లాస్టర్ ఆఫ్ పారిస్ నీటితో జిప్సమ్‌గా గట్టిపడుతుంది.","pts":["ఆమ్లం: పులుపు, నీలి లిట్మస్ → ఎరుపు; క్షారం: చేదు, సబ్బు లాంటి స్పర్శ, ఎరుపు లిట్మస్ → నీలం.","ఫినాఫ్తలీన్: ఆమ్లంలో రంగులేదు, క్షారంలో గులాబీ; మిథైల్ ఆరెంజ్: ఆమ్లంలో ఎరుపు, క్షారంలో పసుపు.","ఆమ్లం + లోహం → లవణం + H₂↑ (మండే పుల్లతో \"పాప్\" శబ్దం).","లోహ కార్బొనేట్ + ఆమ్లం → లవణం + CO₂ + H₂O; CO₂ సున్నపు నీటిని పాలవలె చేస్తుంది.","తటస్థీకరణం: ఆమ్లం + క్షారం → లవణం + నీరు (NaOH + HCl → NaCl + H₂O).","నీటిలో కరిగే క్షారాలు ఆల్కలీలు (NaOH, KOH, Ca(OH)₂).","ఆమ్లాన్ని నీటిలో కలపాలి (నీటిని ఆమ్లంలో కాదు) – ఉష్ణమోచక చర్య, చిమ్ముతుంది.","pH = హైడ్రోజన్ అయాన్ గాఢత కొలత; pH తగ్గితే ఆమ్లత్వం పెరుగుతుంది. సార్వత్రిక సూచిక (universal indicator) రంగుతో pH తెలుస్తుంది.","బ్లీచింగ్ పౌడర్ CaOCl₂, బేకింగ్ సోడా NaHCO₃, వాషింగ్ సోడా Na₂CO₃·10H₂O, ప్లాస్టర్ ఆఫ్ పారిస్ CaSO₄·½H₂O, జిప్సమ్ CaSO₄·2H₂O.","స్ఫటిక జలం: CuSO₄·5H₂O (నీలం) వేడి చేస్తే తెల్లగా అవుతుంది; నీరు కలిపితే మళ్ళీ నీలం."],"w":[["ఆమ్లం","Acid"],["క్షారం","Base"],["ఆల్కలీ","Alkali (నీటిలో కరిగే క్షారం)"],["లవణం","Salt"],["సూచిక","Indicator"],["తటస్థీకరణం","Neutralisation"],["గాఢత","Concentration"],["విలీనం చేయడం","Dilution"],["pH స్కేలు","pH scale (0–14)"],["హైడ్రోనియం అయాన్","Hydronium ion H₃O⁺"],["స్ఫటిక జలం","Water of crystallisation"],["ఆంటాసిడ్","Antacid"]],"gr":{"t":"ముఖ్య సమీకరణాలు","p":["Zn + H₂SO₄ → ZnSO₄ + H₂","Na₂CO₃ + 2HCl → 2NaCl + H₂O + CO₂;  Ca(OH)₂ + CO₂ → CaCO₃ + H₂O (పాల రంగు)","2NaCl + 2H₂O → 2NaOH + Cl₂ + H₂ (క్లోర్–ఆల్కలీ ప్రక్రియ)","Ca(OH)₂ + Cl₂ → CaOCl₂ + H₂O (బ్లీచింగ్ పౌడర్)","NaCl + H₂O + CO₂ + NH₃ → NH₄Cl + NaHCO₃;  2NaHCO₃ → Na₂CO₃ + H₂O + CO₂ (వేడి)","CaSO₄·½H₂O + 1½H₂O → CaSO₄·2H₂O (ప్లాస్టర్ ఆఫ్ పారిస్ → జిప్సమ్)"]},"qa":[["పెరుగు, పుల్లని పదార్థాలు ఇత్తడి/రాగి పాత్రల్లో ఎందుకు ఉంచకూడదు?","అవి ఆమ్లాలు – లోహంతో చర్య జరిపి విషపూరిత లవణాలు ఏర్పడతాయి."],["లోహంతో ఆమ్లం చర్యలో విడుదలయ్యే వాయువు?","హైడ్రోజన్."],["పొడి HCl వాయువు పొడి లిట్మస్ రంగు ఎందుకు మార్చదు?","నీరు లేకుండా H⁺ అయాన్లు ఏర్పడవు."],["pH 6, pH 8 ద్రావణాల్లో ఏది ఎక్కువ H⁺?","pH 6 – అది ఆమ్లం; pH 8 క్షారం."],["గట్టి నీటిని మెత్తబరిచే సోడియం సమ్మేళనం?","సోడియం కార్బొనేట్ (వాషింగ్ సోడా)."],["ప్లాస్టర్ ఆఫ్ పారిస్ తేమ చొరని డబ్బాలో ఎందుకు?","తేమ పీల్చుకుని జిప్సమ్‌గా గట్టిపడుతుంది."]],"act":"ఎర్ర క్యాబేజీ/మందార పూల రసంతో సహజ సూచిక తయారు చేసి నిమ్మరసం, సబ్బు నీరు, వెనిగర్, బేకింగ్ సోడా ద్రావణం, ఉప్పు నీటిలో రంగులు గమనించి ఆమ్లం/క్షారం/తటస్థం పట్టిక రాయండి.","kn":"తేనెటీగ కుట్టినప్పుడు మెథనోయిక్ ఆమ్లం (ఫార్మిక్ ఆమ్లం) వల్ల నొప్పి – బేకింగ్ సోడా వంటి బలహీన క్షారం రాస్తే ఉపశమనం. దురదగొండి ఆకుల్లో కూడా మెథనోయిక్ ఆమ్లం ఉంటుంది; దాని పక్కనే పెరిగే డాక్ ఆకు రసం ఉపశమనం ఇస్తుంది.","qz":[["ఆమ్లం నీలి లిట్మస్‌ను?","ఎరుపుగా మారుస్తుంది","నీలంగానే ఉంచుతుంది","పసుపుగా","ఆకుపచ్చగా"],["ఫినాఫ్తలీన్ క్షారంలో రంగు?","గులాబీ","రంగులేదు","పసుపు","ఎరుపు"],["ఆమ్లం + లోహం → ?","లవణం + హైడ్రోజన్","లవణం + నీరు","లవణం + CO₂","క్షారం + H₂"],["తటస్థీకరణ ఉత్పన్నాలు?","లవణం + నీరు","ఆమ్లం + నీరు","క్షారం + H₂","లవణం + CO₂"],["pH 7 అంటే?","తటస్థం","బలమైన ఆమ్లం","బలమైన క్షారం","బలహీన ఆమ్లం"],["ఎక్కువ H⁺ గాఢత ఉన్నది?","pH 1","pH 4","pH 7","pH 11"],["దంతక్షయం ఏ pH కంటే తక్కువైతే మొదలవుతుంది?","5.5","7","8.5","3"],["బ్లీచింగ్ పౌడర్ ఫార్ములా?","CaOCl₂","CaCl₂","NaOCl","Ca(OH)₂"],["బేకింగ్ సోడా?","NaHCO₃","Na₂CO₃","NaOH","NaCl"],["వాషింగ్ సోడా?","Na₂CO₃·10H₂O","NaHCO₃","CaSO₄·2H₂O","CuSO₄·5H₂O"],["ప్లాస్టర్ ఆఫ్ పారిస్?","CaSO₄·½H₂O","CaSO₄·2H₂O","CaCO₃","CaO"],["అజీర్ణానికి వాడే మందు?","ఆంటాసిడ్","యాంటీబయాటిక్","నొప్పి నివారిణి","యాంటిసెప్టిక్"],["ఆమ్లం విలీనం చేసేటప్పుడు?","ఆమ్లాన్ని నీటిలో నెమ్మదిగా కలపాలి","నీటిని ఆమ్లంలో పోయాలి","ఒక్కసారిగా కలపాలి","వేడి చేసి కలపాలి"],["క్లోర్–ఆల్కలీ ప్రక్రియ ఉత్పన్నాలు?","NaOH, Cl₂, H₂","NaCl, H₂O","Na₂CO₃, CO₂","NaHCO₃, NH₄Cl"],["తేనెటీగ కాటులోని ఆమ్లం?","మెథనోయిక్ ఆమ్లం","లాక్టిక్ ఆమ్లం","సిట్రిక్ ఆమ్లం","టార్టారిక్ ఆమ్లం"],["నీలి కాపర్ సల్ఫేట్ వేడి చేస్తే?","తెల్లగా మారుతుంది (స్ఫటిక జలం పోతుంది)","ఎర్రగా మారుతుంది","నల్లగా మారుతుంది","మారదు"],["ఉల్లిపాయ ఏ రకం సూచిక?","వాసన సూచిక","సంశ్లేషిత సూచిక","సార్వత్రిక సూచిక","లోహ సూచిక"],["క్షార ద్రావణాల్లో H⁺ అయాన్లు?","ఉంటాయి, కానీ OH⁻ కంటే తక్కువ","అస్సలు ఉండవు","OH⁻ కంటే ఎక్కువ","సమానం"]],"wb":{"mis":"\"క్షార ద్రావణంలో H⁺ ఉండదు\" అనుకోవడం తప్పు – ఉంటుంది కానీ OH⁻ ఎక్కువ. pH ఎక్కువైతే ఆమ్లత్వం ఎక్కువ కాదు – తక్కువ. అన్ని క్షారాలు ఆల్కలీలు కావు (నీటిలో కరిగేవే ఆల్కలీలు). ప్లాస్టర్ ఆఫ్ పారిస్‌లో \"అర్ధ\" అణువు నీరు (½H₂O) అంటే రెండు CaSO₄ కు ఒక H₂O.","qz":[["ఎరుపు లిట్మస్‌ను నీలం చేసే ద్రావణం pH?","10","1","4","5"],["గుడ్డు పెంకులతో CO₂ ఇచ్చే ద్రావణంలో ఉన్నది?","HCl","NaCl","LiCl","KCl"],["10 mL NaOH కి 8 mL HCl; 20 mL NaOH కి?","16 mL","8 mL","12 mL","4 mL"],["pH 4, 1, 11, 7, 9 (A–E) – బలమైన ఆమ్లం?","B","A","C","E"],["పై వాటిలో బలహీన క్షారం?","E (pH 9)","C (pH 11)","D (pH 7)","A (pH 4)"],["Mg + HCl, Mg + CH₃COOH – ఎక్కువ బుడగలు?","HCl (బలమైన ఆమ్లం)","CH₃COOH","రెండూ సమానం","చర్య జరగదు"],["పాలు పెరుగుగా మారితే pH?","తగ్గుతుంది","పెరుగుతుంది","మారదు","14 అవుతుంది"],["స్వేదన జలం విద్యుత్ వాహకమా?","కాదు – అయాన్లు లేవు","అవును","కొద్దిగా ఎక్కువ","వేడి చేస్తే మాత్రమే"],["ఆల్కహాల్, గ్లూకోజ్ ఆమ్లాలు కావు ఎందుకు?","నీటిలో H⁺ అయాన్లు ఇవ్వవు","వాటిలో H లేదు","అవి క్షారాలు","అవి లవణాలు"],["పాలవాడు పాలలో బేకింగ్ సోడా కలిపితే పెరుగు?","ఆలస్యంగా తోడుకుంటుంది","త్వరగా తోడుకుంటుంది","అసలు తోడుకోదు","రంగు మారుతుంది"]],"pg":"38–77","f":"books/10/Class10_Physical_Science_Textbook.pdf","p":44,"lb":"పాఠ్యపుస్తకం","ws":["పాఠంలోని ప్రశ్నలు 1 (పుట 48) – 3 ప్రశ్నలు","పాఠంలోని ప్రశ్నలు 2 (పుట 54) – 6 ప్రశ్నలు","పాఠంలోని ప్రశ్నలు 3 (పుట 60) – 4 ప్రశ్నలు","పాఠంలోని ప్రశ్నలు 4 (పుట 70) – 5 ప్రశ్నలు","అభ్యాసాలు – Exercises (పుట 72) – 15 ప్రశ్నలు"]},"tg":[["పాఠంలోని ప్రశ్నలు 1 (పుట 48)",["1) పెరుగు, పుల్లని పదార్థాల్లో ఆమ్లాలు ఉంటాయి. అవి ఇత్తడి, రాగితో చర్య జరిపి విషపూరిత లవణాలు ఏర్పరుస్తాయి (ఆహారం పాడవుతుంది, పాత్ర క్షయం చెందుతుంది)","2) హైడ్రోజన్ వాయువు (H₂) – ఉదా: Zn + 2HCl → ZnCl₂ + H₂","3) A = కాల్షియం కార్బొనేట్. CaCO₃ + 2HCl → CaCl₂ + CO₂ + H₂O; విడుదలైన CO₂ మంటను ఆర్పుతుంది"]],["పాఠంలోని ప్రశ్నలు 2 (పుట 54)",["1) నీటిలో అవి H⁺ (H₃O⁺) అయాన్లు ఇస్తాయి: HCl + H₂O → H₃O⁺ + Cl⁻ – అందుకే ఆమ్ల ధర్మాలు","2) ఆమ్ల ద్రావణంలో H⁺ మొదలైన అయాన్లు ఉంటాయి; అయాన్లు విద్యుత్‌ను మోస్తాయి","3) నీరు లేనప్పుడు HCl అయనీకరణం చెందదు – H⁺ అయాన్లు ఏర్పడవు, కాబట్టి రంగు మారదు","4) ఆమ్లాన్ని నీటిలో కలపడం అతి ఉష్ణమోచక చర్య. నీటిని ఆమ్లంలో పోస్తే వేడికి మిశ్రమం చిమ్మి కాలుతుంది, గాజు పాత్ర పగలవచ్చు. కాబట్టి ఆమ్లాన్ని నీటిలో నెమ్మదిగా, కలుపుతూ పోయాలి","5) ఒక్కో ఘనపరిమాణంలో H₃O⁺ అయాన్ల గాఢత తగ్గుతుంది (విలీనం)","6) OH⁻ అయాన్ల గాఢత పెరుగుతుంది (కొంత వరకు, ద్రావణం సంతృప్తం అయ్యే వరకు)"]],["పాఠంలోని ప్రశ్నలు 3 (పుట 60)",["1) A (pH 6) లో H⁺ గాఢత ఎక్కువ. A ఆమ్లం, B (pH 8) క్షారం","2) H⁺ గాఢత ఎక్కువైతే ద్రావణం ఎక్కువ ఆమ్లం (pH తక్కువ); తక్కువైతే తక్కువ ఆమ్లం/క్షారం","3) అవును, క్షార ద్రావణాల్లో కూడా H⁺ ఉంటాయి. కానీ వాటిలో OH⁻ అయాన్లు H⁺ కంటే ఎక్కువ – అందుకే క్షారం","4) నేల మరీ ఆమ్లంగా ఉన్నప్పుడు (pH తక్కువ) – సున్నం (CaO), తేలిన సున్నం (Ca(OH)₂) లేదా సుద్ద (CaCO₃) వేస్తారు"]],["పాఠంలోని ప్రశ్నలు 4 (పుట 70)",["1) బ్లీచింగ్ పౌడర్","2) తేలిన సున్నం – కాల్షియం హైడ్రాక్సైడ్: Ca(OH)₂ + Cl₂ → CaOCl₂ + H₂O","3) సోడియం కార్బొనేట్ (వాషింగ్ సోడా) Na₂CO₃·10H₂O","4) వేడి చేస్తే వియోగం చెందుతుంది: 2NaHCO₃ → Na₂CO₃ + H₂O + CO₂","5) CaSO₄·½H₂O + 1½H₂O → CaSO₄·2H₂O (జిప్సమ్ – గట్టిపడుతుంది)"]],["అభ్యాసాలు – Exercises (పుట 72)",["1) (d) 10 – ఎరుపు లిట్మస్ నీలం అయితే క్షారం, pH > 7","2) (b) HCl – CaCO₃ + 2HCl → CaCl₂ + H₂O + CO₂","3) (d) 16 mL – NaOH రెట్టింపు, కాబట్టి HCl కూడా రెట్టింపు","4) (c) ఆంటాసిడ్ (ఉదా: మెగ్నీషియం హైడ్రాక్సైడ్ – మిల్క్ ఆఫ్ మెగ్నీషియా)","5) (a) జింక్ + సల్ఫ్యూరిక్ ఆమ్లం → జింక్ సల్ఫేట్ + హైడ్రోజన్: Zn + H₂SO₄ → ZnSO₄ + H₂ (b) మెగ్నీషియం + హైడ్రోక్లోరిక్ ఆమ్లం → మెగ్నీషియం క్లోరైడ్ + హైడ్రోజన్: Mg + 2HCl → MgCl₂ + H₂ (c) అల్యూమినియం + సల్ఫ్యూరిక్ ఆమ్లం → అల్యూమినియం సల్ఫేట్ + హైడ్రోజన్: 2Al + 3H₂SO₄ → Al₂(SO₄)₃ + 3H₂ (d) ఇనుము + హైడ్రోక్లోరిక్ ఆమ్లం → ఫెర్రస్ క్లోరైడ్ + హైడ్రోజన్: Fe + 2HCl → FeCl₂ + H₂","6) కృత్యం: బీకరులో గ్లూకోజ్ ద్రావణం, ఆల్కహాల్ ద్రావణం (వేర్వేరుగా), సజల HCl తీసుకోండి. కార్క్‌పై రెండు మేకులు బిగించి బల్బు, 6 V బ్యాటరీ, స్విచ్‌తో కలపండి. HCl లో బల్బు వెలుగుతుంది; గ్లూకోజ్, ఆల్కహాల్‌లో వెలగదు → అవి H⁺ అయాన్లు ఇవ్వవు, కాబట్టి ఆమ్లాలు కావు","7) స్వేదన జలంలో అయాన్లు ఉండవు; వర్షపు నీరు గాలిలోని CO₂, SO₂ వంటి వాయువులను కరిగించుకుని అయాన్లు కలిగి ఉంటుంది – అందుకే విద్యుత్ వాహకం","8) ఆమ్ల ధర్మాలకు కారణం H⁺ (H₃O⁺) అయాన్లు; అవి నీటిలోనే ఏర్పడతాయి","9) (a) తటస్థం: D (pH 7) (b) బలమైన క్షారం: C (pH 11) (c) బలమైన ఆమ్లం: B (pH 1) (d) బలహీన ఆమ్లం: A (pH 4) (e) బలహీన క్షారం: E (pH 9). H⁺ గాఢత పెరిగే క్రమం: C (11) < E (9) < D (7) < A (4) < B (1)","10) A (HCl) లో ఎక్కువ బుడగలు – HCl బలమైన ఆమ్లం, ఎక్కువ H⁺ అయాన్లు; CH₃COOH బలహీన ఆమ్లం","11) పెరుగులో లాక్టిక్ ఆమ్లం ఏర్పడుతుంది, కాబట్టి pH 6 కంటే తగ్గుతుంది (ఎక్కువ ఆమ్లం)","12) (a) కొద్దిగా క్షారం చేస్తే పాలు త్వరగా పుల్లబడవు, ఎక్కువ సేపు నిల్వ ఉంటాయి (b) తోడుకునేటప్పుడు ఏర్పడే లాక్టిక్ ఆమ్లం ముందుగా బేకింగ్ సోడాను తటస్థీకరించాలి – అందుకే ఆలస్యం","13) ప్లాస్టర్ ఆఫ్ పారిస్ తేమను పీల్చుకుని జిప్సమ్‌గా మారి గట్టి ముద్దగా అవుతుంది (CaSO₄·½H₂O + 1½H₂O → CaSO₄·2H₂O) – వాడకానికి పనికిరాదు","14) ఆమ్లం, క్షారం చర్య జరిపి లవణం, నీరు ఏర్పడటం తటస్థీకరణం. ఉదా: NaOH + HCl → NaCl + H₂O; Mg(OH)₂ + 2HCl → MgCl₂ + 2H₂O (ఆంటాసిడ్)","15) వాషింగ్ సోడా: గాజు, సబ్బు, కాగితం పరిశ్రమల్లో; గట్టి నీటిని మెత్తబరచడానికి; ఇంటి శుభ్రతకు. బేకింగ్ సోడా: బేకింగ్ పౌడర్ (కేకులు మెత్తగా); ఆంటాసిడ్; సోడా–ఆమ్ల అగ్నిమాపక యంత్రాల్లో"]]],"by":"భౌతిక శాస్త్రం 10వ తరగతి (పుటలు 38–77)"},{"id":"ph3","no":3,"t":"లోహాలు, అలోహాలు (Metals and Non-metals)","m":[8,9],"ty":"Chapter 3","th":"భౌతిక–రసాయన ధర్మాలు, చర్యాశీలత శ్రేణి, అయానిక సమ్మేళనాలు, లోహ సంగ్రహణం, క్షయ నివారణ","sum":"లోహాలు మెరుపు గలవి, కొట్టి రేకులుగా (స్తరణీయత), లాగి తీగలుగా (తాంతవత) మార్చవచ్చు, ఉష్ణ–విద్యుత్ వాహకాలు, ధ్వనిని ఇస్తాయి (sonorous). మినహాయింపులు: పాదరసం ద్రవం, సోడియం–పొటాషియం మెత్తనివి, గ్యాలియం–సీజియం చేతిలో కరుగుతాయి; అలోహాల్లో గ్రాఫైట్ విద్యుత్ వాహకం, వజ్రం అత్యంత గట్టిది, అయోడిన్‌కు మెరుపు. లోహ ఆక్సైడ్లు క్షార ధర్మం, అలోహ ఆక్సైడ్లు ఆమ్ల ధర్మం; Al₂O₃, ZnO ద్విస్వభావ (amphoteric). చర్యాశీలత శ్రేణి: K > Na > Ca > Mg > Al > Zn > Fe > Pb > H > Cu > Hg > Ag > Au. లోహాలు ఎలక్ట్రాన్లు కోల్పోయి, అలోహాలు గ్రహించి అయానిక సమ్మేళనాలు (NaCl, MgCl₂) ఏర్పడతాయి – ఇవి అధిక ద్రవీభవన స్థానం, నీటిలో కరిగి/ద్రవ స్థితిలో విద్యుత్ వాహకం. ఖనిజాల నుండి లోహ సంగ్రహణం: సాంద్రీకరణ → (కాల్సినేషన్/రోస్టింగ్) → క్షయకరణం → విద్యుత్ శోధనం. తుప్పు నివారణ: పెయింట్, గ్రీజు, గాల్వనైజింగ్, మిశ్రలోహాలు.","pts":["లోహాలు: మెరుపు, స్తరణీయత, తాంతవత, ఉష్ణ–విద్యుత్ వాహకత, ధ్వని (sonorous). వెండి, రాగి ఉత్తమ వాహకాలు; సీసం, పాదరసం తక్కువ.","లోహం + ఆక్సిజన్ → క్షార ఆక్సైడ్ (2Cu + O₂ → 2CuO); Al₂O₃, ZnO ద్విస్వభావ ఆక్సైడ్లు.","Na, K గాలిలో మండిపోతాయి కాబట్టి కిరోసిన్‌లో ఉంచుతారు; Mg వేడి నీటితో, Fe ఆవిరితో మాత్రమే చర్య జరుపుతాయి; Cu, Ag, Au నీటితో చర్య జరపవు.","లోహం + సజల ఆమ్లం → లవణం + H₂ (Cu, Ag, Au తప్ప); HNO₃ బలమైన ఆక్సీకారి కాబట్టి H₂ సాధారణంగా రాదు (Mg, Mn తప్ప).","ఎక్కువ చర్యాశీల లోహం తక్కువ దాన్ని లవణ ద్రావణం నుండి స్థానభ్రంశం చేస్తుంది (Zn + FeSO₄ → ZnSO₄ + Fe).","అయానిక బంధం: Na (2,8,1) ఎలక్ట్రాన్ కోల్పోయి Na⁺, Cl (2,8,7) గ్రహించి Cl⁻ → NaCl.","ఖనిజం (mineral), ధాతువు (ore – లాభదాయకంగా లోహం తీయగలిగేది), గాంగ్ (gangue – మలినాలు).","తక్కువ చర్యాశీల లోహాలు (Hg) వేడి చేస్తేనే; మధ్యస్థ (Zn, Fe) – కార్బన్‌తో క్షయకరణం; అధిక (Na, Mg, Al) – ద్రవ క్లోరైడ్/ఆక్సైడ్ విద్యుద్విశ్లేషణ.","విద్యుత్ శోధనం: ఆనోడ్ – అశుద్ధ లోహం, కాథోడ్ – శుద్ధ లోహపు పలక, విద్యుద్విశ్లేష్యం – ఆ లోహ లవణ ద్రావణం.","మిశ్రలోహాలు: ఇత్తడి (Cu + Zn), కంచు (Cu + Sn), టంకము (Pb + Sn), స్టెయిన్‌లెస్ స్టీల్ (Fe + Ni + Cr); అమాల్గమ్ = పాదరసం మిశ్రలోహం."],"w":[["లోహం / అలోహం","Metal / Non-metal"],["స్తరణీయత","Malleability"],["తాంతవత","Ductility"],["ధ్వనించే","Sonorous"],["ద్విస్వభావ ఆక్సైడ్","Amphoteric oxide"],["చర్యాశీలత శ్రేణి","Reactivity series"],["అయానిక సమ్మేళనం","Ionic compound"],["ఖనిజం / ధాతువు","Mineral / Ore"],["గాంగ్","Gangue"],["భస్మీకరణం / భర్జనం","Calcination / Roasting"],["విద్యుత్ శోధనం","Electrolytic refining"],["మిశ్రలోహం","Alloy"]],"gr":{"t":"ముఖ్య చర్యలు","p":["2Na + 2H₂O → 2NaOH + H₂ + ఉష్ణం;  3Fe + 4H₂O(ఆవిరి) → Fe₃O₄ + 4H₂","Al₂O₃ + 6HCl → 2AlCl₃ + 3H₂O;  Al₂O₃ + 2NaOH → 2NaAlO₂ + H₂O (ద్విస్వభావం)","2ZnS + 3O₂ → 2ZnO + 2SO₂ (భర్జనం);  ZnCO₃ → ZnO + CO₂ (భస్మీకరణం);  ZnO + C → Zn + CO","2HgS + 3O₂ → 2HgO + 2SO₂;  2HgO → 2Hg + O₂","Fe₂O₃ + 2Al → 2Fe + Al₂O₃ + ఉష్ణం (థర్మిట్ – రైలు పట్టాల అతుకు)"]},"qa":[["గది ఉష్ణోగ్రత వద్ద ద్రవ లోహం?","పాదరసం (Hg)."],["సోడియం కిరోసిన్‌లో ఎందుకు?","గాలి, తేమతో తీవ్రంగా చర్య జరిపి మండిపోతుంది."],["జింక్‌ను FeSO₄ ద్రావణంలో వేస్తే?","Zn + FeSO₄ → ZnSO₄ + Fe; లేత ఆకుపచ్చ రంగు పోతుంది."],["అయానిక సమ్మేళనాల ద్రవీభవన స్థానం ఎక్కువ ఎందుకు?","ధన–ఋణ అయాన్ల మధ్య బలమైన ఆకర్షణ బలాలు విడదీయడానికి ఎక్కువ శక్తి కావాలి."],["ప్రకృతిలో స్వేచ్ఛా స్థితిలో దొరికే లోహాలు?","బంగారం, ప్లాటినం (వెండి, రాగి కొంత)."],["ద్విస్వభావ ఆక్సైడ్లు అంటే?","ఆమ్లం, క్షారం రెండింటితో చర్య జరిపి లవణం, నీరు ఇచ్చేవి – Al₂O₃, ZnO."]],"act":"ఇనుము, రాగి, అల్యూమినియం, బొగ్గు, సల్ఫర్ ముక్కలను సుత్తితో కొట్టి, బ్యాటరీ–బల్బు సర్క్యూట్‌లో పెట్టి స్తరణీయత, వాహకత పట్టిక తయారు చేయండి. ఇనుప మేకులను మూడు పరీక్షనాళికల్లో (నీరు+గాలి; మరిగించిన నీరు+నూనె; పొడి గాలి+CaCl₂) ఉంచి వారం తర్వాత తుప్పు గమనించండి.","kn":"ఢిల్లీలోని కుతుబ్ మినార్ దగ్గర ఉన్న ఇనుప స్తంభం 1600 సంవత్సరాలకు పైగా తుప్పు పట్టకుండా ఉంది – ప్రాచీన భారతీయ లోహ శాస్త్ర నైపుణ్యానికి నిదర్శనం. 24 క్యారెట్ బంగారం మెత్తగా ఉంటుంది; ఆభరణాలకు 22 క్యారెట్ (22 భాగాలు బంగారం + 2 భాగాలు రాగి/వెండి) వాడతారు.","qz":[["గది ఉష్ణోగ్రత వద్ద ద్రవ రూపంలో ఉండే లోహం?","పాదరసం","సోడియం","గ్యాలియం","బ్రోమిన్"],["కత్తితో కోయగలిగే లోహం?","సోడియం","ఇనుము","రాగి","అల్యూమినియం"],["విద్యుత్ వాహకమైన అలోహం?","గ్రాఫైట్","వజ్రం","సల్ఫర్","అయోడిన్"],["లోహ ఆక్సైడ్లు సాధారణంగా?","క్షార ధర్మం","ఆమ్ల ధర్మం","తటస్థం","ఎప్పుడూ ద్విస్వభావం"],["ద్విస్వభావ ఆక్సైడ్?","ZnO","Na₂O","CO₂","SO₂"],["కిరోసిన్‌లో నిల్వ చేసే లోహం?","సోడియం","ఇనుము","రాగి","వెండి"],["ఆవిరితో మాత్రమే చర్య జరిపే లోహం?","ఇనుము","సోడియం","పొటాషియం","కాల్షియం"],["చర్యాశీలత అత్యధికం?","పొటాషియం","జింక్","రాగి","బంగారం"],["Zn + CuSO₄ → ?","ZnSO₄ + Cu","చర్య జరగదు","CuO + ZnS","Zn(OH)₂"],["NaCl ఏ బంధం?","అయానిక","సంయోజక","లోహ","హైడ్రోజన్"],["ధాతువులోని మలినాలు?","గాంగ్","ఖనిజం","మిశ్రలోహం","అమాల్గమ్"],["సల్ఫైడ్ ధాతువును గాలిలో వేడి చేయడం?","భర్జనం (roasting)","భస్మీకరణం","విద్యుత్ శోధనం","స్వేదనం"],["విద్యుత్ శోధనంలో ఆనోడ్?","అశుద్ధ లోహం","శుద్ధ లోహం","గ్రాఫైట్ మాత్రమే","ప్లాటినం"],["ఇత్తడి (brass) లో లోహాలు?","రాగి + జింక్","రాగి + తగరం","సీసం + తగరం","ఇనుము + కార్బన్"],["టంకము (solder)?","సీసం + తగరం","రాగి + జింక్","ఇనుము + నికెల్","అల్యూమినియం + రాగి"],["గాల్వనైజింగ్ అంటే ఇనుముపై ___ పూత","జింక్","తగరం","రాగి","క్రోమియం"],["థర్మిట్ చర్యలో వాడే లోహం?","అల్యూమినియం","రాగి","సోడియం","వెండి"],["సజల HNO₃ తో H₂ ఇచ్చే లోహాలు?","Mg, Mn","Cu, Ag","Fe, Zn","Na, K"]],"wb":{"mis":"\"అన్ని లోహాలు గట్టిగా ఉంటాయి\" అనడం తప్పు (Na, K మెత్తనివి). జింక్ తగరం కంటే ఎక్కువ చర్యాశీలం – అందుకే ఆహార డబ్బాలకు తగరం పూత. అయానిక సమ్మేళనాలు ఘన స్థితిలో విద్యుత్ వాహకాలు కావు – కరిగినప్పుడు లేదా ద్రావణంలో మాత్రమే. భస్మీకరణం = గాలి లేకుండా (కార్బొనేట్), భర్జనం = గాలిలో (సల్ఫైడ్).","qz":[["స్థానభ్రంశ చర్య జరిగే జత?","AgNO₃ ద్రావణం + రాగి","NaCl ద్రావణం + రాగి","MgCl₂ ద్రావణం + అల్యూమినియం","FeSO₄ ద్రావణం + వెండి"],["ఇనుప బాణలి తుప్పు నివారణ?","పైవన్నీ","గ్రీజు మాత్రమే","పెయింట్ మాత్రమే","జింక్ పూత మాత్రమే"],["ఆక్సిజన్‌తో అధిక ద్రవీభవన, నీటిలో కరిగే సమ్మేళనం ఇచ్చే మూలకం?","కాల్షియం","కార్బన్","సిలికాన్","ఇనుము"],["ఆహార డబ్బాలకు జింక్ కాకుండా తగరం పూత ఎందుకు?","జింక్ తగరం కంటే ఎక్కువ చర్యాశీలం","జింక్ ఖరీదు","జింక్ ద్రవీభవన స్థానం ఎక్కువ","జింక్ తక్కువ చర్యాశీలం"],["సజల ఆమ్లాల నుండి H₂ ను స్థానభ్రంశం చేయని లోహాలు?","రాగి, వెండి","జింక్, మెగ్నీషియం","ఇనుము, అల్యూమినియం","సోడియం, కాల్షియం"],["సల్ఫర్ మండించిన వాయువు తడి నీలి లిట్మస్‌ను?","ఎరుపుగా మారుస్తుంది","నీలంగానే ఉంచుతుంది","తెల్లగా చేస్తుంది","ఆకుపచ్చగా"],["అలోహాలు ఆక్సిజన్‌తో ఏర్పరిచే ఆక్సైడ్లు?","ఆమ్ల లేదా తటస్థ","క్షార","ద్విస్వభావ మాత్రమే","అయానిక"],["మసకబారిన రాగి పాత్రలను శుభ్రం చేసేది?","నిమ్మ/చింతపండు (ఆమ్లం)","ఉప్పు నీరు","సబ్బు మాత్రమే","కిరోసిన్"],["వేడి నీటి ట్యాంకులకు రాగి ఎందుకు?","నీటితో చర్య జరపదు, తుప్పు పట్టదు","చౌక","బరువు తక్కువ","అయస్కాంతం"],["బంగారాన్ని కరిగించే ఆక్వా రీజియా?","3 HCl : 1 HNO₃","1 HCl : 3 HNO₃","HCl + H₂SO₄","HNO₃ మాత్రమే"]],"pg":"78–119","f":"books/10/Class10_Physical_Science_Textbook.pdf","p":84,"lb":"పాఠ్యపుస్తకం","ws":["పాఠంలోని ప్రశ్నలు 1 (పుట 84) – 2 ప్రశ్నలు","పాఠంలోని ప్రశ్నలు 2 (పుట 96) – 5 ప్రశ్నలు","పాఠంలోని ప్రశ్నలు 3 (పుట 102) – 2 ప్రశ్నలు","పాఠంలోని ప్రశ్నలు 4 (పుట 110) – 3 ప్రశ్నలు","పాఠంలోని ప్రశ్నలు 5 (పుట 114) – 3 ప్రశ్నలు","అభ్యాసాలు – Exercises (పుట 116) – 16 ప్రశ్నలు"]},"tg":[["పాఠంలోని ప్రశ్నలు 1 (పుట 84)",["1) (i) గది ఉష్ణోగ్రత వద్ద ద్రవం: పాదరసం (ii) కత్తితో కోయగలిగేది: సోడియం/పొటాషియం (iii) ఉత్తమ ఉష్ణ వాహకం: వెండి (రాగి) (iv) తక్కువ ఉష్ణ వాహకం: సీసం/పాదరసం","2) స్తరణీయత (malleable): సుత్తితో కొట్టి పలుచని రేకులుగా మార్చగలగడం (ఉదా: అల్యూమినియం ఫాయిల్). తాంతవత (ductile): లాగి సన్నని తీగలుగా మార్చగలగడం (ఉదా: రాగి తీగ)"]],["పాఠంలోని ప్రశ్నలు 2 (పుట 96)",["1) సోడియం గాలిలోని ఆక్సిజన్, తేమతో తీవ్రంగా చర్య జరిపి మండిపోతుంది; కిరోసిన్‌తో చర్య జరపదు కాబట్టి అందులో ఉంచుతారు","2) (i) 3Fe(s) + 4H₂O(g) → Fe₃O₄(s) + 4H₂(g) (ii) Ca(s) + 2H₂O(l) → Ca(OH)₂(aq) + H₂(g); 2K(s) + 2H₂O(l) → 2KOH(aq) + H₂(g) + ఉష్ణం","3) (i) అత్యంత చర్యాశీలం: B (FeSO₄ నుండి Fe ను స్థానభ్రంశం చేసింది) (ii) B ను CuSO₄ లో వేస్తే స్థానభ్రంశం జరిగి రాగి పూత, నీలం రంగు తగ్గుతుంది (B, Fe కంటే చర్యాశీలం కాబట్టి Cu కంటే కూడా) (iii) తగ్గే క్రమం: B > A > C > D","4) హైడ్రోజన్ వాయువు. Fe + H₂SO₄ → FeSO₄ + H₂","5) జింక్ ఇనుము కంటే ఎక్కువ చర్యాశీలం – లేత ఆకుపచ్చ రంగు పోయి, జింక్‌పై ఇనుము పూత ఏర్పడుతుంది. Zn + FeSO₄ → ZnSO₄ + Fe"]],["పాఠంలోని ప్రశ్నలు 3 (పుట 102)",["1) (i) Na· (బయటి కక్ష్యలో 1 చుక్క), O (6 చుక్కలు), Mg (2 చుక్కలు) (ii) Na₂O: 2Na → 2Na⁺ + 2e⁻; O + 2e⁻ → O²⁻ → (Na⁺)₂O²⁻. MgO: Mg → Mg²⁺ + 2e⁻; O + 2e⁻ → O²⁻ → Mg²⁺O²⁻ (iii) Na₂O లో Na⁺, O²⁻; MgO లో Mg²⁺, O²⁻ అయాన్లు","2) ధన, ఋణ అయాన్ల మధ్య బలమైన స్థిర విద్యుత్ ఆకర్షణ బలాలు ఉంటాయి; వాటిని విడదీయడానికి చాలా శక్తి కావాలి – అందుకే ద్రవీభవన స్థానం ఎక్కువ"]],["పాఠంలోని ప్రశ్నలు 4 (పుట 110)",["1) (i) ఖనిజం: భూపటలంలో సహజంగా దొరికే మూలకాలు/సమ్మేళనాలు (ii) ధాతువు: లాభదాయకంగా లోహం సంగ్రహించగల ఖనిజం (iii) గాంగ్: ధాతువులో ఉండే మట్టి, ఇసుక వంటి మలినాలు","2) బంగారం, ప్లాటినం (వెండి కూడా)","3) క్షయకరణం – ఆక్సైడ్‌ను కార్బన్ (కోక్) తో వేడి చేయడం (ZnO + C → Zn + CO); అధిక చర్యాశీల లోహాలకు విద్యుద్విశ్లేషణ"]],["పాఠంలోని ప్రశ్నలు 5 (పుట 114)",["1) ZnO + Mg → MgO + Zn (స్థానభ్రంశం); CuO + Zn → ZnO + Cu; CuO + Mg → MgO + Cu. MgO తో Zn, Cu చర్య జరపవు; ZnO తో Cu చర్య జరపదు","2) బంగారం, ప్లాటినం (వెండి తక్కువ) – తక్కువ చర్యాశీల లోహాలు","3) రెండు లేదా అంతకంటే ఎక్కువ లోహాల (లేదా లోహం + అలోహం) సజాతీయ మిశ్రమం మిశ్రలోహం. ఉదా: ఇత్తడి (Cu + Zn), కంచు (Cu + Sn), స్టీల్ (Fe + C)"]],["అభ్యాసాలు – Exercises (పుట 116)",["1) (d) AgNO₃ ద్రావణం, రాగి – Cu + 2AgNO₃ → Cu(NO₃)₂ + 2Ag","2) (d) పైవన్నీ","3) (a) కాల్షియం – CaO అయానిక, అధిక ద్రవీభవన స్థానం, నీటిలో కరుగుతుంది","4) (c) జింక్ తగరం కంటే ఎక్కువ చర్యాశీలం (ఆహార ఆమ్లాలతో చర్య జరుపుతుంది)","5) (a) సుత్తి: లోహం రేకుగా మారుతుంది (స్తరణీయం), అలోహం ముక్కలవుతుంది (పెళుసు). బ్యాటరీ–బల్బు–తీగలు–స్విచ్: నమూనాను సర్క్యూట్‌లో పెడితే లోహం అయితే బల్బు వెలుగుతుంది (b) ఈ పరీక్షలు చాలావరకు ఉపయోగకరం, కానీ మినహాయింపులు ఉన్నాయి – గ్రాఫైట్ (అలోహం) విద్యుత్ వాహకం; Na, K మెత్తనివి","6) ఆమ్లం, క్షారం రెండింటితో చర్య జరిపి లవణం, నీరు ఇచ్చే లోహ ఆక్సైడ్లు. ఉదా: Al₂O₃, ZnO","7) స్థానభ్రంశం చేసేవి: జింక్, మెగ్నీషియం (ఇనుము). చేయనివి: రాగి, వెండి (బంగారం)","8) ఆనోడ్: అశుద్ధ లోహం M; కాథోడ్: శుద్ధ M పలుచని పలక; విద్యుద్విశ్లేష్యం: M యొక్క నీటిలో కరిగే లవణ ద్రావణం","9) వాయువు SO₂. (a) (i) పొడి లిట్మస్‌పై ప్రభావం లేదు (ii) తడి నీలి లిట్మస్ ఎరుపవుతుంది (SO₂ + H₂O → H₂SO₃ ఆమ్లం) (b) S + O₂ → SO₂","10) (i) పెయింట్/నూనె/గ్రీజు రాయడం (ii) గాల్వనైజింగ్ – జింక్ పూత (మిశ్రలోహం చేయడం కూడా)","11) ఆమ్ల ఆక్సైడ్లు (ఉదా: CO₂, SO₂); కొన్ని తటస్థం (CO, H₂O)","12) (a) ప్లాటినం, బంగారం, వెండి మెరుపు గలవి, తక్కువ చర్యాశీలం – మసకబారవు, తుప్పు పట్టవు (b) సోడియం, పొటాషియం, లిథియం అతి చర్యాశీలం – గాలిలో మండిపోతాయి, కాబట్టి నూనెలో నిల్వ (c) అల్యూమినియం చర్యాశీలమైనా దానిపై Al₂O₃ రక్షణ పొర ఏర్పడుతుంది; తేలిక, మంచి ఉష్ణ వాహకం – వంట పాత్రలకు అనుకూలం (d) సల్ఫైడ్, కార్బొనేట్ కంటే ఆక్సైడ్ నుండి లోహం పొందడం (క్షయకరణం) సులభం – అందుకే ముందు ఆక్సైడ్‌గా మారుస్తారు","13) రాగి పాత్రలపై తేమ, CO₂ వల్ల పచ్చని బేసిక్ కాపర్ కార్బొనేట్ పొర ఏర్పడుతుంది. నిమ్మ, చింతపండులోని ఆమ్లాలు ఆ క్షార పొరను కరిగిస్తాయి – పాత్ర మెరుస్తుంది","14) లోహాలు: ఆక్సిజన్‌తో క్షార ఆక్సైడ్లు; సజల ఆమ్లాల నుండి H₂ ఇస్తాయి; ఎలక్ట్రాన్లు కోల్పోయి ధన అయాన్లు; క్లోరిన్‌తో అయానిక క్లోరైడ్లు. అలోహాలు: ఆమ్ల/తటస్థ ఆక్సైడ్లు; ఆమ్లాల నుండి H₂ ఇవ్వవు; ఎలక్ట్రాన్లు గ్రహించి ఋణ అయాన్లు; క్లోరిన్‌తో సంయోజక క్లోరైడ్లు","15) అతను ఆక్వా రీజియా (3 భాగాలు గాఢ HCl : 1 భాగం గాఢ HNO₃) వాడాడు. అది బంగారం బయటి పొరను కరిగించింది – అందుకే మెరుపు వచ్చినా బరువు తగ్గింది","16) రాగి నీటితో (వేడి నీరు, ఆవిరి కూడా) చర్య జరపదు, తుప్పు పట్టదు, మంచి ఉష్ణ వాహకం. స్టీల్ (ఇనుము) తేమతో తుప్పు పడుతుంది"]]],"by":"భౌతిక శాస్త్రం 10వ తరగతి (పుటలు 78–119)"},{"id":"ph4","no":4,"t":"కార్బన్, దాని సమ్మేళనాలు (Carbon and its Compounds)","m":[10],"ty":"Chapter 4","th":"సంయోజక బంధం, శృంఖలీకరణం, హైడ్రోకార్బన్లు, ప్రమేయ సమూహాలు, సజాతీయ శ్రేణి, ఇథనాల్–ఇథనోయిక్ ఆమ్లం, సబ్బులు–డిటర్జెంట్లు","sum":"కార్బన్ (2, 4) నాలుగు ఎలక్ట్రాన్లు కోల్పోవడం గానీ, గ్రహించడం గానీ కష్టం – అందుకే ఎలక్ట్రాన్లను పంచుకుని సంయోజక బంధాలు (covalent bonds) ఏర్పరుస్తుంది. ఏక, ద్వి, త్రి బంధాలు (H₂, O₂, N₂). సంయోజక సమ్మేళనాలకు తక్కువ ద్రవీభవన/బాష్పీభవన స్థానాలు, విద్యుత్ వాహకత ఉండదు. కార్బన్ ప్రత్యేకత: శృంఖలీకరణం (catenation – తనలో తాను బంధించుకుని పొడవైన గొలుసులు, శాఖలు, వలయాలు) మరియు చతుస్సంయోజకత (tetravalency). సంతృప్త హైడ్రోకార్బన్లు ఆల్కేన్లు (ఏక బంధాలు, CₙH₂ₙ₊₂), అసంతృప్తం ఆల్కీన్లు (ద్వి బంధం, CₙH₂ₙ), ఆల్కైన్లు (త్రి బంధం, CₙH₂ₙ₋₂). ఒకే అణు ఫార్ములా, వేర్వేరు నిర్మాణాలు – నిర్మాణ సాదృశ్యకాలు (isomers). ప్రమేయ సమూహాలు: –Cl/–Br (హాలో), –OH (ఆల్కహాల్), –CHO (ఆల్డిహైడ్), >C=O (కీటోన్), –COOH (కార్బాక్సిలిక్ ఆమ్లం). సజాతీయ శ్రేణిలో వరుస సభ్యులు CH₂ తేడాతో ఉంటాయి. రసాయన చర్యలు: దహనం, ఆక్సీకరణం, సంకలనం (హైడ్రోజనీకరణం), ప్రతిక్షేపణం. ఇథనాల్, ఇథనోయిక్ ఆమ్లం ధర్మాలు; ఎస్టరీకరణం; సబ్బు మిసెల్లుల శుభ్రపరిచే విధానం.","pts":["సంయోజక బంధం: ఎలక్ట్రాన్ జతలను పంచుకోవడం; CH₄ లో 4 ఏక బంధాలు, O₂ లో ద్వి బంధం, N₂ లో త్రి బంధం.","కార్బన్ రూపాంతరాలు: వజ్రం (అతి గట్టిది, విద్యుత్ అవాహకం), గ్రాఫైట్ (మెత్తనిది, విద్యుత్ వాహకం), ఫుల్లరీన్ (C₆₀).","శృంఖలీకరణం + చతుస్సంయోజకత = లక్షలాది కార్బన్ సమ్మేళనాలు.","ఆల్కేన్: CₙH₂ₙ₊₂ (మీథేన్, ఈథేన్); ఆల్కీన్: CₙH₂ₙ (ఈథీన్); ఆల్కైన్: CₙH₂ₙ₋₂ (ఈథైన్).","పేర్లు: పదం మూలం (meth-1, eth-2, prop-3, but-4, pent-5, hex-6) + ప్రత్యయం (-ane, -ene, -yne, -ol, -al, -one, -oic acid).","సజాతీయ శ్రేణి: ఒకే ప్రమేయ సమూహం, వరుస సభ్యుల మధ్య –CH₂– (14 u) తేడా, రసాయన ధర్మాలు ఒకేలా.","సంతృప్త హైడ్రోకార్బన్లు నీలి మంట; అసంతృప్తం పసుపు మసి మంట.","ఇథనాల్ + Na → సోడియం ఇథాక్సైడ్ + H₂; ఇథనాల్ గాఢ H₂SO₄ తో 443 K వద్ద → ఈథీన్ (నిర్జలీకరణం).","ఇథనోయిక్ ఆమ్లం (5–8% = వెనిగర్) + NaHCO₃ → CO₂ బుడగలు; + ఆల్కహాల్ → ఎస్టర్ (తియ్యని వాసన).","సబ్బు: పొడవైన కార్బాక్సిలిక్ ఆమ్లాల Na/K లవణాలు; గట్టి నీటితో Ca²⁺, Mg²⁺ వల్ల తెట్టు (scum). డిటర్జెంట్లు గట్టి నీటిలో కూడా నురుగు ఇస్తాయి."],"w":[["సంయోజక బంధం","Covalent bond"],["శృంఖలీకరణం","Catenation"],["చతుస్సంయోజకత","Tetravalency"],["రూపాంతరాలు","Allotropes"],["సంతృప్త / అసంతృప్త","Saturated / Unsaturated"],["హైడ్రోకార్బన్","Hydrocarbon"],["సాదృశ్యకాలు","Isomers"],["ప్రమేయ సమూహం","Functional group"],["సజాతీయ శ్రేణి","Homologous series"],["ఎస్టరీకరణం","Esterification"],["హైడ్రోజనీకరణం","Hydrogenation"],["మిసెల్","Micelle"]],"gr":{"t":"ముఖ్య చర్యలు","p":["CH₄ + 2O₂ → CO₂ + 2H₂O + ఉష్ణం, కాంతి (దహనం)","CH₃CH₂OH —(క్షార KMnO₄ / ఆమ్లీకృత K₂Cr₂O₇)→ CH₃COOH (ఆక్సీకరణం)","R₂C=CR₂ + H₂ —(Ni/Pd ఉత్ప్రేరకం)→ R₂CH–CHR₂ (సంకలనం)","CH₄ + Cl₂ —(సూర్యకాంతి)→ CH₃Cl + HCl (ప్రతిక్షేపణం)","CH₃COOH + CH₃CH₂OH —(ఆమ్లం)→ CH₃COOCH₂CH₃ + H₂O (ఎస్టరీకరణం)","CH₃COOC₂H₅ + NaOH → C₂H₅OH + CH₃COONa (సపోనిఫికేషన్ – సబ్బు తయారీ)"]},"qa":[["CO₂ ఎలక్ట్రాన్ చుక్కల నిర్మాణం?","O::C::O – C, ప్రతి O తో రెండు ఎలక్ట్రాన్ జతలు (ద్వి బంధాలు) పంచుకుంటుంది."],["పెంటేన్‌కు ఎన్ని నిర్మాణ సాదృశ్యకాలు?","మూడు – n-పెంటేన్, ఐసోపెంటేన్, నియోపెంటేన్."],["ఇథనాల్ నుండి ఇథనోయిక్ ఆమ్లం ఆక్సీకరణం ఎందుకు?","అణువులో ఆక్సిజన్ కలుస్తుంది (హైడ్రోజన్ తొలగుతుంది)."],["వెల్డింగ్‌కు ఆక్సిజన్ + ఈథైన్ ఎందుకు?","పూర్తి దహనంతో చాలా ఎక్కువ ఉష్ణోగ్రత వస్తుంది; గాలితో అసంపూర్ణ దహనం, తక్కువ ఉష్ణోగ్రత."],["ఆల్కహాల్, కార్బాక్సిలిక్ ఆమ్లాన్ని ఎలా గుర్తిస్తాం?","NaHCO₃ కలిపితే ఆమ్లం CO₂ బుడగలు ఇస్తుంది; ఆల్కహాల్ ఇవ్వదు."],["హైడ్రోజనీకరణం పరిశ్రమలో ఉపయోగం?","నికెల్ ఉత్ప్రేరకంతో కూరగాయల నూనెలు → వనస్పతి నెయ్యి."]],"act":"ఇంట్లో వాడే నూనె కొద్దిగా ఒక గ్లాసులో నీటిలో, మరో గ్లాసులో సబ్బు నీటిలో వేసి కలపండి – సబ్బు నీటిలో నూనె చిన్న బిందువులుగా (మిసెల్లు) కలిసిపోవడం చూడండి. కుళాయి నీరు, బావి నీటిలో సబ్బు నురుగు పోల్చి గట్టి నీటిని గుర్తించండి.","kn":"కార్బన్ సమ్మేళనాలు దాదాపు 30 లక్షలకు పైగా తెలుసు – మిగిలిన అన్ని మూలకాల సమ్మేళనాల కంటే ఎక్కువ! తాగే ఆల్కహాల్‌లో మిథనాల్ కలిస్తే విషం – అంధత్వం, మరణం సంభవించవచ్చు; పారిశ్రామిక ఆల్కహాల్‌కు మిథనాల్, రంగు కలిపి \"డీనేచర్డ్\" చేస్తారు.","qz":[["కార్బన్ ఏర్పరిచే బంధాలు ప్రధానంగా?","సంయోజక","అయానిక","లోహ","హైడ్రోజన్"],["C₂H₆ లో సంయోజక బంధాలు?","7","6","8","9"],["N₂ లో బంధం?","త్రి బంధం","ఏక బంధం","ద్వి బంధం","అయానిక"],["విద్యుత్ వాహకమైన కార్బన్ రూపాంతరం?","గ్రాఫైట్","వజ్రం","ఫుల్లరీన్","కార్బన్ మోనాక్సైడ్"],["ఆల్కీన్ సాధారణ ఫార్ములా?","CₙH₂ₙ","CₙH₂ₙ₊₂","CₙH₂ₙ₋₂","CₙHₙ"],["పెంటేన్ సాదృశ్యకాలు?","3","2","4","5"],["బ్యూటనోన్ ప్రమేయ సమూహం?","కీటోన్","ఆల్డిహైడ్","ఆల్కహాల్","కార్బాక్సిలిక్ ఆమ్లం"],["–CHO ప్రమేయ సమూహం?","ఆల్డిహైడ్","కీటోన్","ఆల్కహాల్","ఆమ్లం"],["సజాతీయ శ్రేణి వరుస సభ్యుల తేడా?","CH₂ (14 u)","CH₄","C₂H₄","H₂"],["సంకలన చర్య జరిపేది?","C₂H₂","C₂H₆","CH₄","C₃H₈"],["వెనిగర్ అంటే?","5–8% ఇథనోయిక్ ఆమ్ల ద్రావణం","ఇథనాల్","మిథనాల్","ఎస్టర్"],["ఎస్టర్ వాసన?","తియ్యని (పండ్ల)","కుళ్ళిన గుడ్డు","ఘాటైన","వాసన లేదు"],["గట్టి నీటిలో సబ్బు ఏర్పరిచేది?","తెట్టు (scum)","నురుగు ఎక్కువ","ఎస్టర్","మిసెల్ మాత్రమే"],["పాత్ర అడుగు నల్లబడితే?","ఇంధనం పూర్తిగా మండటం లేదు","ఆహారం ఉడకలేదు","ఇంధనం తడి","పూర్తిగా మండుతోంది"],["వనస్పతి తయారీలో ఉత్ప్రేరకం?","నికెల్","ఇనుము","రాగి","జింక్"],["CH₃CH₂Br పేరు?","బ్రోమోఈథేన్","బ్రోమోమీథేన్","ఈథనాల్","బ్రోమోప్రొపేన్"],["HCHO పేరు?","Methanal (మిథనాల్ – ఆల్డిహైడ్)","Methanol","Ethanal","Methanoic acid"],["సబ్బు లిట్మస్‌తో?","ఎరుపు లిట్మస్ నీలం (క్షారం)","నీలి లిట్మస్ ఎరుపు","మార్పు లేదు","రెండూ తెల్లగా"]],"wb":{"mis":"C₂H₆ లో బంధాలు 6 కాదు – C–C ఒకటి + C–H ఆరు = 7. మిథనాల్ (–OH, ఆల్కహాల్) మరియు మిథనాల్ (HCHO, ఆల్డిహైడ్) తెలుగులో ఒకేలా వినిపిస్తాయి – ఇంగ్లీష్‌లో methanol / methanal గమనించండి. సంకలన చర్య అసంతృప్త హైడ్రోకార్బన్లకే; ప్రతిక్షేపణం సంతృప్త వాటికి.","qz":[["ఈథేన్‌లో సంయోజక బంధాలు?","7","6","8","9"],["బ్యూటనోన్ ప్రమేయ సమూహం?","కీటోన్","కార్బాక్సిలిక్ ఆమ్లం","ఆల్డిహైడ్","ఆల్కహాల్"],["వంట పాత్ర అడుగు బయట నల్లబడితే?","ఇంధనం పూర్తిగా మండటం లేదు","ఆహారం ఉడకలేదు","ఇంధనం తడిగా ఉంది","ఇంధనం పూర్తిగా మండుతోంది"],["CH₃Cl లో కార్బన్ ఎన్ని ఎలక్ట్రాన్లు పంచుకుంటుంది?","4","3","2","1"],["సంకలన చర్య జరిపే హైడ్రోకార్బన్లు?","C₃H₆, C₂H₂","C₂H₆, CH₄","C₃H₈, C₂H₆","CH₄, C₃H₈"],["సంతృప్త–అసంతృప్త తేడా తెలిపే పరీక్ష?","బ్రోమిన్ నీటి రంగు పోవడం","లిట్మస్","NaHCO₃","సున్నపు నీరు"],["ఇథనాల్‌లో మిసెల్లు ఏర్పడతాయా?","ఏర్పడవు","ఏర్పడతాయి","కొన్నిసార్లు","నీటి కంటే ఎక్కువ"],["ఇథనోయిక్ ఆమ్లం శీతాకాలంలో గడ్డకడుతుంది – దాని పేరు?","గ్లేషియల్ అసిటిక్ ఆమ్లం","వెనిగర్","ఎస్టర్","డీనేచర్డ్ ఆల్కహాల్"],["సబ్బు మిసెల్‌లో లోపలికి ఉండే భాగం?","హైడ్రోకార్బన్ తోక (నూనెను ఆకర్షించేది)","అయానిక తల","నీరు","Na⁺"],["కార్బన్ సమ్మేళనాలు ఇంధనాలుగా ఎందుకు?","అధిక ఉష్ణ విలువ, స్వచ్ఛంగా మండుతాయి","చౌక మాత్రమే","మండవు","విద్యుత్ ఇస్తాయి"]],"pg":"120–161","f":"books/10/Class10_Physical_Science_Textbook.pdf","p":126,"lb":"పాఠ్యపుస్తకం","ws":["పాఠంలోని ప్రశ్నలు 1 (పుట 126) – 2 ప్రశ్నలు","పాఠంలోని ప్రశ్నలు 2 (పుట 140) – 5 ప్రశ్నలు","పాఠంలోని ప్రశ్నలు 3 (పుట 146) – 2 ప్రశ్నలు","పాఠంలోని ప్రశ్నలు 4 (పుట 152) – 2 ప్రశ్నలు","పాఠంలోని ప్రశ్నలు 5 (పుట 156) – 2 ప్రశ్నలు","అభ్యాసాలు – Exercises (పుట 158) – 15 ప్రశ్నలు"]},"tg":[["పాఠంలోని ప్రశ్నలు 1 (పుట 126)",["1) CO₂: కార్బన్ ప్రతి ఆక్సిజన్‌తో రెండు ఎలక్ట్రాన్ జతలు పంచుకుంటుంది – O::C::O (O=C=O, రెండు ద్వి బంధాలు)","2) S₈: ఎనిమిది సల్ఫర్ పరమాణువులు కిరీటం ఆకార వలయం; ప్రతి S పక్కనున్న రెండు S లతో ఒక్కో ఎలక్ట్రాన్ జత పంచుకుంటుంది (ఏక బంధాలు), ప్రతి S పై రెండు ఒంటరి జతలు"]],["పాఠంలోని ప్రశ్నలు 2 (పుట 140)",["1) మూడు: n-పెంటేన్ CH₃–CH₂–CH₂–CH₂–CH₃; ఐసోపెంటేన్ (2-మిథైల్‌బ్యూటేన్) CH₃–CH(CH₃)–CH₂–CH₃; నియోపెంటేన్ (2,2-డైమిథైల్‌ప్రొపేన్) C(CH₃)₄","2) (i) శృంఖలీకరణం – తనతో తాను బంధించుకుని పొడవైన గొలుసులు, శాఖలు, వలయాలు (ii) చతుస్సంయోజకత – 4 సంయోజకత వల్ల అనేక మూలకాలతో బంధాలు","3) సైక్లోపెంటేన్ C₅H₁₀ – ఐదు కార్బన్ల వలయం, ప్రతి కార్బన్‌కు రెండు H; ప్రతి C–C, C–H బంధం ఒక ఎలక్ట్రాన్ జత","4) (i) ఇథనోయిక్ ఆమ్లం CH₃–COOH (ii) బ్రోమోపెంటేన్ CH₃–CH₂–CH₂–CH₂–CH₂–Br; అవును, సాదృశ్యకాలు సాధ్యం – 1-, 2-, 3-బ్రోమోపెంటేన్ (iii) బ్యూటనోన్ CH₃–CO–CH₂–CH₃ (iv) హెక్సనాల్ (hexanal) CH₃–CH₂–CH₂–CH₂–CH₂–CHO","5) CH₃–CH₂–Br: బ్రోమోఈథేన్; HCHO: మిథనాల్ (methanal); CH≡C–CH₂–CH₂–CH₂–CH₃: హెక్సైన్ (1-హెక్సైన్)"]],["పాఠంలోని ప్రశ్నలు 3 (పుట 146)",["1) ఇథనాల్ (CH₃CH₂OH) కు ఆక్సిజన్ కలిసి (రెండు H తొలగి) ఇథనోయిక్ ఆమ్లం (CH₃COOH) అవుతుంది – ఆక్సిజన్ గ్రహించడం = ఆక్సీకరణం (క్షార KMnO₄ / ఆమ్లీకృత K₂Cr₂O₇ ఆక్సీకారులు)","2) శుద్ధ ఆక్సిజన్‌తో ఈథైన్ పూర్తిగా మండి అతి ఎక్కువ ఉష్ణోగ్రత (≈3000 °C) ఇస్తుంది – లోహాలు కరుగుతాయి. గాలితో కలిపితే అసంపూర్ణ దహనం, మసి మంట, తక్కువ ఉష్ణోగ్రత"]],["పాఠంలోని ప్రశ్నలు 4 (పుట 152)",["1) రెండింటికీ NaHCO₃ (లేదా Na₂CO₃) కలపండి – కార్బాక్సిలిక్ ఆమ్లం CO₂ బుడగలు ఇస్తుంది (సున్నపు నీరు పాలవలె); ఆల్కహాల్ ఇవ్వదు. (నీలి లిట్మస్ ఆమ్లంలో ఎరుపవుతుంది)","2) ఇతర పదార్థాలకు ఆక్సిజన్‌ను అందించే పదార్థాలు ఆక్సీకారులు – ఉదా: క్షార పొటాషియం పర్మాంగనేట్, ఆమ్లీకృత పొటాషియం డైక్రోమేట్"]],["పాఠంలోని ప్రశ్నలు 5 (పుట 156)",["1) లేదు – డిటర్జెంట్లు గట్టి, మెత్తని నీరు రెండింటిలోనూ నురుగు ఇస్తాయి. గట్టి నీటిని సబ్బుతో పరీక్షించాలి (తెట్టు ఏర్పడుతుంది)","2) సబ్బు మిసెల్లు జిడ్డు మురికిని పట్టుకుంటాయి; బట్టలను కొట్టడం, రుద్దడం, కలపడం వల్ల మురికి కణాలు బట్ట నుండి విడిపోయి నీటిలోకి వస్తాయి – అందుకే శుభ్రత"]],["అభ్యాసాలు – Exercises (పుట 158)",["1) (b) 7 సంయోజక బంధాలు (1 C–C + 6 C–H)","2) (c) కీటోన్ (CH₃COCH₂CH₃)","3) (b) ఇంధనం పూర్తిగా మండటం లేదు (అసంపూర్ణ దహనం – మసి)","4) CH₃Cl లో కార్బన్ (2, 4) తన 4 వేలన్సీ ఎలక్ట్రాన్లను మూడు H లతో ఒక్కొక్కటి, ఒక Cl తో ఒకటి పంచుకుని నాలుగు ఏక సంయోజక బంధాలు ఏర్పరుస్తుంది; అన్ని పరమాణువులు స్థిర ఎలక్ట్రాన్ విన్యాసం పొందుతాయి","5) (a) ఇథనోయిక్ ఆమ్లం CH₃COOH: C–H మూడు, C–C, C=O (ద్వి బంధం – రెండు జతలు), C–O–H (b) H₂S: H:S:H – S పై రెండు ఒంటరి జతలు (c) ప్రొపనోన్ CH₃COCH₃: మధ్య C కు O తో ద్వి బంధం (d) F₂: F:F – ఒక జత పంచుకుంటాయి, ప్రతి F పై మూడు ఒంటరి జతలు","6) ఒకే ప్రమేయ సమూహం కలిగి, వరుస సభ్యుల మధ్య –CH₂– తేడా ఉండి, ఒకేలాంటి రసాయన ధర్మాలు, క్రమంగా మారే భౌతిక ధర్మాలు ఉన్న సమ్మేళనాల శ్రేణి సజాతీయ శ్రేణి. ఉదా: ఆల్కేన్లు CH₄, C₂H₆, C₃H₈; ఆల్కహాల్‌లు CH₃OH, C₂H₅OH, C₃H₇OH","7) భౌతిక: ఇథనాల్ – ద్రవం, ఆహ్లాదకర వాసన, బాష్పీభవన స్థానం 351 K; ఇథనోయిక్ ఆమ్లం – వెనిగర్ వాసన, ద్రవీభవన స్థానం 290 K (చలికి గడ్డకడుతుంది). రసాయన: ఇథనోయిక్ ఆమ్లం నీలి లిట్మస్‌ను ఎరుపు చేస్తుంది, NaHCO₃ తో CO₂ ఇస్తుంది; ఇథనాల్ ఇవ్వదు","8) సబ్బు అణువుకు ఒక చివర అయానిక (నీటిని ఆకర్షించే) తల, మరో చివర పొడవైన హైడ్రోకార్బన్ (నీటిని వికర్షించే) తోక. నీటిలో తోకలు లోపలికి, తలలు బయటకు ఉండేలా గుంపుగా చేరి మిసెల్లు ఏర్పడతాయి. ఇథనాల్ వంటి ద్రావణాల్లో హైడ్రోకార్బన్ తోక కూడా కరుగుతుంది – మిసెల్లు ఏర్పడవు","9) అవి గాలిలో మండి ఎక్కువ ఉష్ణం, కాంతి ఇస్తాయి (అధిక ఉష్ణ విలువ), నియంత్రిత దహనం, సులభంగా దొరుకుతాయి, నిల్వ–రవాణా సులభం","10) గట్టి నీటిలోని కాల్షియం, మెగ్నీషియం లవణాలు సబ్బుతో చర్య జరిపి కరగని అవక్షేపం (తెట్టు) ఏర్పరుస్తాయి – నురుగు రాదు, సబ్బు వృథా","11) సబ్బు క్షార స్వభావం – ఎరుపు లిట్మస్ నీలం అవుతుంది; నీలి లిట్మస్‌లో మార్పు లేదు","12) నికెల్/పల్లాడియం ఉత్ప్రేరకం సమక్షంలో అసంతృప్త హైడ్రోకార్బన్‌కు హైడ్రోజన్ కలపడం హైడ్రోజనీకరణం. పరిశ్రమలో కూరగాయల నూనెల నుండి వనస్పతి నెయ్యి తయారీ","13) C₃H₆ (ప్రొపీన్) మరియు C₂H₂ (ఈథైన్) – అసంతృప్తాలు కాబట్టి సంకలన చర్యలు జరుపుతాయి","14) బ్రోమిన్ నీరు (ఎరుపు–గోధుమ) కలిపితే అసంతృప్త హైడ్రోకార్బన్ దాని రంగును పోగొడుతుంది (సంకలనం); సంతృప్తం పోగొట్టదు. (లేదా మండిస్తే అసంతృప్తం పసుపు మసి మంట)","15) మురికి సాధారణంగా జిడ్డుగా ఉండి నీటిలో కరగదు. సబ్బు అణువుల హైడ్రోకార్బన్ తోకలు జిడ్డులోకి చొచ్చుకుపోయి, అయానిక తలలు నీటి వైపు ఉండేలా మిసెల్‌లుగా మురికిని చుట్టుముడతాయి. మిసెల్‌లు నీటిలో తేలియాడుతాయి; నీటితో కడిగితే మురికి పోతుంది"]]],"by":"భౌతిక శాస్త్రం 10వ తరగతి (పుటలు 120–161)"},{"id":"ph9","no":9,"t":"కాంతి – పరావర్తనం, వక్రీభవనం (Light – Reflection and Refraction)","m":[7],"ty":"Chapter 9","th":"గోళాకార దర్పణాలు, దర్పణ సూత్రం, వక్రీభవన నియమాలు, వక్రీభవన గుణకం, కటకాలు, కటక సూత్రం, సామర్థ్యం","sum":"కాంతి సరళరేఖలో ప్రయాణిస్తుంది. పరావర్తన నియమాలు: పతన కోణం = పరావర్తన కోణం; పతన కిరణం, పరావర్తన కిరణం, లంబం ఒకే తలంలో. గోళాకార దర్పణాలు – పుటాకార (concave, అభిసారి) మరియు కుంభాకార (convex, అపసారి). ధ్రువం P, వక్రతా కేంద్రం C, ప్రధాన నాభి F; R = 2f. పుటాకార దర్పణం వస్తువు స్థానాన్ని బట్టి నిజ/మిథ్యా ప్రతిబింబాలు ఇస్తుంది; కుంభాకార దర్పణం ఎప్పుడూ మిథ్యా, నిటారు, చిన్న ప్రతిబింబం (వాహనాల వెనుక చూపు దర్పణం). కార్టీజియన్ గుర్తు పద్ధతితో దర్పణ సూత్రం 1/v + 1/u = 1/f, ఆవర్ధనం m = h′/h = −v/u. కాంతి ఒక యానకం నుండి మరో యానకంలోకి వెళ్ళినప్పుడు దిశ మారడం వక్రీభవనం; స్నెల్ నియమం sin i / sin r = స్థిరాంకం. వక్రీభవన గుణకం n = c/v. కుంభాకార కటకం (అభిసారి), పుటాకార కటకం (అపసారి); కటక సూత్రం 1/v − 1/u = 1/f, m = v/u. కటక సామర్థ్యం P = 1/f (మీటర్లలో), యూనిట్ డయాప్టర్ (D); కుంభాకార +, పుటాకార −.","pts":["పరావర్తన నియమాలు: ∠i = ∠r; పతన కిరణం, పరావర్తన కిరణం, లంబం ఒకే తలంలో.","R = 2f (వక్రతా వ్యాసార్ధం = రెట్టింపు నాభ్యంతరం).","పుటాకార దర్పణం: వస్తువు C కి ఆవల → F, C మధ్య చిన్న, తలకిందులు, నిజ; C వద్ద → C వద్ద సమాన పరిమాణం; F, P మధ్య → దర్పణం వెనుక పెద్ద, నిటారు, మిథ్యా.","కుంభాకార దర్పణం: ఎప్పుడూ దర్పణం వెనుక P, F మధ్య మిథ్యా, నిటారు, చిన్న ప్రతిబింబం – విశాల దృష్టి క్షేత్రం.","గుర్తు పద్ధతి: దూరాలు ధ్రువం/దృక్ కేంద్రం నుండి; కాంతి దిశలో ధనం, వ్యతిరేకంగా ఋణం; పైకి ధనం, కిందకు ఋణం. వస్తువు దూరం u ఎప్పుడూ ఋణం.","దర్పణ సూత్రం 1/v + 1/u = 1/f; m = −v/u. కటక సూత్రం 1/v − 1/u = 1/f; m = v/u. m ఋణం → నిజ, తలకిందులు.","వక్రీభవనం: విరళ → సాంద్ర యానకం – లంబం వైపు వంగుతుంది; సాంద్ర → విరళ – లంబానికి దూరంగా.","n = c/v; n₂₁ = v₁/v₂. వజ్రం n = 2.42 (అత్యధికం); నీరు 1.33; గాజు 1.5.","కుంభాకార కటకం: 2F₁ కి ఆవల వస్తువు → F₂, 2F₂ మధ్య చిన్న నిజ ప్రతిబింబం; F₁, O మధ్య → అదే వైపు పెద్ద మిథ్యా (భూతద్దం). పుటాకార కటకం: ఎప్పుడూ మిథ్యా, నిటారు, చిన్నది.","సామర్థ్యం P = 1/f (m); 1 D = 1 m నాభ్యంతర కటకం సామర్థ్యం. కటకాల సమూహం: P = P₁ + P₂ + …"],"w":[["పరావర్తనం","Reflection"],["వక్రీభవనం","Refraction"],["పుటాకార దర్పణం","Concave mirror"],["కుంభాకార దర్పణం","Convex mirror"],["ధ్రువం","Pole (P)"],["ప్రధాన నాభి","Principal focus (F)"],["నాభ్యంతరం","Focal length (f)"],["వక్రతా కేంద్రం","Centre of curvature (C)"],["నిజ / మిథ్యా ప్రతిబింబం","Real / Virtual image"],["ఆవర్ధనం","Magnification (m)"],["వక్రీభవన గుణకం","Refractive index (n)"],["కటక సామర్థ్యం","Power of lens (D)"]],"gr":{"t":"సూత్రాలు","p":["దర్పణం: 1/v + 1/u = 1/f;  m = h′/h = −v/u;  f = R/2","కటకం: 1/v − 1/u = 1/f;  m = h′/h = v/u","P = 1/f (f మీటర్లలో) – డయాప్టర్ (D)","n = c/v;  n₂₁ = n₂/n₁ = v₁/v₂;  sin i / sin r = n₂₁","ఉదా: కుంభాకార కటకం f = 10 cm, u = −25 cm → 1/v = 1/10 − 1/25 = 3/50 → v = +16.7 cm (నిజ, తలకిందులు)."]},"qa":[["పుటాకార దర్పణ ప్రధాన నాభి నిర్వచనం?","ప్రధానాక్షానికి సమాంతర కిరణాలు పరావర్తనం చెంది ప్రధానాక్షంపై కలిసే బిందువు."],["R = 20 cm అయితే f?","f = R/2 = 10 cm."],["వాహనాల వెనుక చూపుకు కుంభాకార దర్పణం ఎందుకు?","ఎప్పుడూ నిటారు, చిన్న ప్రతిబింబం; విశాలమైన దృష్టి క్షేత్రం."],["గాజు n = 1.5 అయితే గాజులో కాంతి వేగం?","v = c/n = 3×10⁸ / 1.5 = 2×10⁸ m/s."],["1 డయాప్టర్ అంటే?","1 m నాభ్యంతరం గల కటకం సామర్థ్యం."],["f = −2 m పుటాకార కటకం సామర్థ్యం?","P = 1/(−2) = −0.5 D."]],"act":"స్టీల్ చెంచా లోపలి (పుటాకార), బయటి (కుంభాకార) వైపుల్లో మీ ముఖ ప్రతిబింబం పోల్చండి. కుంభాకార కటకంతో సూర్యకాంతిని కాగితంపై కేంద్రీకరించి (టీచర్ పర్యవేక్షణలో) నాభ్యంతరం సుమారుగా కొలవండి. గ్లాసు నీటిలో పెన్సిల్ వంగినట్లు కనిపించడం గమనించండి.","kn":"సౌర కుక్కర్లు, టార్చ్ లైట్లలో పుటాకార దర్పణాలు; ATM లు, షాపుల భద్రతా దర్పణాలుగా కుంభాకార దర్పణాలు వాడతారు. వజ్రం అధిక వక్రీభవన గుణకం వల్లే అంతగా మెరుస్తుంది.","qz":[["పతన కోణం = ?","పరావర్తన కోణం","వక్రీభవన కోణం","90°","0°"],["R = 20 cm దర్పణం f?","10 cm","20 cm","40 cm","5 cm"],["నిటారు, పెద్ద ప్రతిబింబం ఇచ్చే దర్పణం?","పుటాకార (F, P మధ్య వస్తువు)","కుంభాకార","సమతల","ఏదీ కాదు"],["వెనుక చూపు దర్పణం?","కుంభాకార","పుటాకార","సమతల","స్థూపాకార"],["వాహన హెడ్‌లైట్లలో?","పుటాకార దర్పణం","కుంభాకార దర్పణం","సమతల దర్పణం","కుంభాకార కటకం"],["కుంభాకార దర్పణ ప్రతిబింబం?","ఎప్పుడూ మిథ్యా, నిటారు, చిన్నది","నిజ, తలకిందులు","పెద్దది","సమాన పరిమాణం"],["గాలి నుండి నీటిలోకి వక్రంగా వెళ్ళే కాంతి?","లంబం వైపు వంగుతుంది","లంబానికి దూరంగా","వంగదు","వెనక్కి వస్తుంది"],["అత్యధిక వక్రీభవన గుణకం?","వజ్రం","గాజు","నీరు","కిరోసిన్"],["n = c/v లో v అంటే?","యానకంలో కాంతి వేగం","శూన్యంలో వేగం","తరంగదైర్ఘ్యం","పౌనఃపున్యం"],["కటక సామర్థ్యం యూనిట్?","డయాప్టర్","మీటర్","వాట్","ఓమ్"],["P = −2 D అయితే f?","−0.5 m (పుటాకార)","+0.5 m","−2 m","+2 m"],["+1.5 D కటకం?","అభిసారి (కుంభాకార), f = 0.67 m","అపసారి","సమతల","f = 1.5 m"],["కటకాలకు పనికిరానిది?","మట్టి","గాజు","నీరు","ప్లాస్టిక్"],["సమతల దర్పణం ఆవర్ధనం +1 అంటే?","సమాన పరిమాణం, నిటారు","రెట్టింపు","చిన్నది","తలకిందులు"],["చిన్న అక్షరాలు చదవడానికి?","కుంభాకార కటకం f = 5 cm","పుటాకార కటకం f = 5 cm","కుంభాకార f = 50 cm","పుటాకార f = 50 cm"],["కుంభాకార కటకంతో వస్తువు సమాన పరిమాణ నిజ ప్రతిబింబం – వస్తువు?","2F వద్ద","F వద్ద","అనంతం వద్ద","O, F మధ్య"],["సగం కటకం నల్ల కాగితంతో కప్పితే?","పూర్తి ప్రతిబింబం, కాంతి తక్కువ","సగం ప్రతిబింబం","ప్రతిబింబం రాదు","రెట్టింపు"],["దర్పణం, కటకం రెండింటి f = −15 cm అయితే?","రెండూ పుటాకారం","రెండూ కుంభాకారం","దర్పణం పుటాకార, కటకం కుంభాకార","దర్పణం కుంభాకార, కటకం పుటాకార"]],"wb":{"mis":"గుర్తు పద్ధతి మరిచిపోవడం అతి పెద్ద తప్పు – u ఎప్పుడూ ఋణం; పుటాకార దర్పణం/కటకం f ఋణం, కుంభాకార f ధనం (దర్పణంలో కుంభాకారం f +, కటకంలో కుంభాకారం f +; పుటాకార దర్పణం f −, పుటాకార కటకం f −). దర్పణ సూత్రం (1/v + 1/u) మరియు కటక సూత్రం (1/v − 1/u) కలపకూడదు. P = 1/f లో f మీటర్లలోనే.","qz":[["మిథ్యా, నిటారు, పెద్ద ప్రతిబింబం (పుటాకార దర్పణం) – వస్తువు?","ధ్రువం, నాభి మధ్య","F, C మధ్య","C వద్ద","C కి ఆవల"],["పుటాకార దర్పణం f = 15 cm, నిటారు ప్రతిబింబం కోసం వస్తువు దూరం?","0 నుండి 15 cm లోపు","15–30 cm","30 cm","30 cm కి ఆవల"],["5 cm వస్తువు, 25 cm దూరం, కుంభాకార కటకం f = 10 cm – ప్రతిబింబ దూరం?","16.7 cm","25 cm","10 cm","6.7 cm"],["పుటాకార కటకం f = 15, ప్రతిబింబం 10 cm – వస్తువు దూరం?","30 cm","15 cm","6 cm","25 cm"],["కుంభాకార దర్పణం f = 15, వస్తువు 10 cm – ప్రతిబింబం?","6 cm దర్పణం వెనుక","30 cm ముందు","6 cm ముందు","15 cm వెనుక"],["పై లెక్కలో ఆవర్ధనం?","0.6","−0.6","1.5","−1.5"],["7 cm వస్తువు, 27 cm, పుటాకార దర్పణం f = 18 – ప్రతిబింబ దూరం?","54 cm దర్పణం ముందు","54 cm వెనుక","27 cm ముందు","18 cm"],["పై లెక్కలో ప్రతిబింబ పరిమాణం?","14 cm (తలకిందులు)","7 cm","3.5 cm","21 cm"],["కుంభాకార దర్పణం R = 32 cm – f?","16 cm","32 cm","64 cm","8 cm"],["మూడు రెట్లు ఆవర్ధన నిజ ప్రతిబింబం, వస్తువు 10 cm (పుటాకార) – ప్రతిబింబం?","30 cm దర్పణం ముందు","30 cm వెనుక","3.3 cm","10 cm"]],"pg":"162–215","f":"books/10/Class10_Physical_Science_Textbook.pdf","p":168,"lb":"పాఠ్యపుస్తకం","ws":["పాఠంలోని ప్రశ్నలు 1 (పుట 178) – 4 ప్రశ్నలు","పాఠంలోని ప్రశ్నలు 2 (పుట 184) – 2 ప్రశ్నలు","పాఠంలోని ప్రశ్నలు 3 (పుట 194) – 5 ప్రశ్నలు","పాఠంలోని ప్రశ్నలు 4 (పుట 210) – 3 ప్రశ్నలు","అభ్యాసాలు – Exercises (పుట 212) – 17 ప్రశ్నలు"]},"tg":[["పాఠంలోని ప్రశ్నలు 1 (పుట 178)",["1) ప్రధానాక్షానికి సమాంతరంగా వచ్చే కిరణాలు పుటాకార దర్పణంపై పరావర్తనం చెంది ప్రధానాక్షంపై కలిసే బిందువు ప్రధాన నాభి (F)","2) f = R/2 = 20/2 = 10 cm","3) పుటాకార దర్పణం (వస్తువు ధ్రువం, నాభి మధ్య ఉన్నప్పుడు)","4) కుంభాకార దర్పణం ఎప్పుడూ నిటారు, చిన్న ప్రతిబింబం ఇస్తుంది; బయటకు వంగి ఉండటం వల్ల విశాల దృష్టి క్షేత్రం – వెనుక ఎక్కువ ప్రాంతం కనిపిస్తుంది"]],["పాఠంలోని ప్రశ్నలు 2 (పుట 184)",["1) f = R/2 = 32/2 = +16 cm","2) నిజ ప్రతిబింబం → m = −3 = −v/u. u = −10 cm → v = 3u = −30 cm. ప్రతిబింబం దర్పణం ముందు 30 cm వద్ద"]],["పాఠంలోని ప్రశ్నలు 3 (పుట 194)",["1) అవును, నీరు సాంద్రతర యానకం కాబట్టి కాంతి లంబం వైపు వంగుతుంది (వేగం తగ్గుతుంది)","2) v = c/n = (3 × 10⁸)/1.50 = 2 × 10⁸ m/s","3) పట్టిక 9.3 లో అత్యధిక దృశ్య సాంద్రత వజ్రం (n = 2.42); అత్యల్పం గాలి (n = 1.0003)","4) వక్రీభవన గుణకాలు: కిరోసిన్ 1.44, టర్పెంటైన్ 1.47, నీరు 1.33. n తక్కువైతే వేగం ఎక్కువ – నీటిలో కాంతి అత్యంత వేగంగా ప్రయాణిస్తుంది","5) వజ్రంలో కాంతి వేగం శూన్యంలో (గాలిలో) వేగంలో 1/2.42 వంతు: n = c/v = 2.42"]],["పాఠంలోని ప్రశ్నలు 4 (పుట 210)",["1) 1 మీటరు నాభ్యంతరం గల కటకం సామర్థ్యం 1 డయాప్టర్ (1 D = 1 m⁻¹)","2) ప్రతిబింబం సమాన పరిమాణం, నిజ → వస్తువు 2F వద్ద. v = +50 cm → u = −50 cm. 2f = 50 → f = 25 cm = 0.25 m. P = 1/0.25 = +4 D. సూది కటకం ముందు 50 cm వద్ద","3) f = −2 m → P = 1/f = −0.5 D"]],["అభ్యాసాలు – Exercises (పుట 212)",["1) (d) మట్టి (పారదర్శకం కాదు)","2) (d) దర్పణ ధ్రువం, ప్రధాన నాభి మధ్య","3) (b) నాభ్యంతరానికి రెట్టింపు దూరంలో (2F వద్ద)","4) (a) రెండూ పుటాకారం (f ఋణం)","5) (d) సమతల లేదా కుంభాకార","6) (c) 5 cm నాభ్యంతరం గల కుంభాకార కటకం (ఎక్కువ ఆవర్ధనం)","7) వస్తువు దూరం 0 నుండి 15 cm లోపు (ధ్రువం, నాభి మధ్య). ప్రతిబింబం మిథ్యా, నిటారు, వస్తువు కంటే పెద్దది, దర్పణం వెనుక. (కిరణ చిత్రం: P, F మధ్య వస్తువు నుండి సమాంతర కిరణం F గుండా, C వైపు కిరణం తిరిగి అదే దారిలో – వెనక్కి పొడిగిస్తే దర్పణం వెనుక కలుస్తాయి)","8) (a) కారు హెడ్‌లైట్లు: పుటాకార దర్పణం – F వద్ద బల్బు, శక్తివంతమైన సమాంతర కాంతి కిరణాలు (b) సైడ్/వెనుక చూపు దర్పణం: కుంభాకారం – నిటారు, విశాల దృష్టి (c) సౌర కొలిమి: పుటాకారం – సూర్యకాంతిని నాభి వద్ద కేంద్రీకరించి అధిక ఉష్ణం","9) అవును, పూర్తి ప్రతిబింబం వస్తుంది – మిగిలిన సగం కటకం గుండా కాంతి కిరణాలు అన్ని బిందువుల నుండి వెళ్తాయి; కానీ ప్రతిబింబం కాంతి తీవ్రత తగ్గుతుంది. పరీక్ష: సగం కటకం కప్పి దూరపు వస్తువు ప్రతిబింబాన్ని తెరపై పట్టి చూడండి","10) h = 5 cm, u = −25 cm, f = +10 cm. 1/v = 1/f + 1/u = 1/10 − 1/25 = 3/50 → v = +16.7 cm. m = v/u = 16.7/(−25) = −0.67; h′ = −3.3 cm. ప్రతిబింబం కటకం అవతల 16.7 cm వద్ద, నిజ, తలకిందులు, చిన్నది (3.3 cm)","11) f = −15 cm, v = −10 cm (పుటాకార కటకం – అదే వైపు). 1/u = 1/v − 1/f = −1/10 + 1/15 = −1/30 → u = −30 cm. వస్తువు కటకం ముందు 30 cm వద్ద. (కిరణ చిత్రం: సమాంతర కిరణం వక్రీభవనం చెంది F₁ నుండి వచ్చినట్లు; O గుండా కిరణం వంగదు)","12) u = −10 cm, f = +15 cm. 1/v = 1/f − 1/u = 1/15 + 1/10 = 1/6 → v = +6 cm. ప్రతిబింబం దర్పణం వెనుక 6 cm, మిథ్యా, నిటారు, m = −v/u = 0.6 (చిన్నది)","13) ప్రతిబింబం వస్తువుతో సమాన పరిమాణం (|m| = 1); + గుర్తు – ప్రతిబింబం నిటారు, మిథ్యా","14) h = 5 cm, u = −20 cm, R = 30 → f = +15 cm. 1/v = 1/15 + 1/20 = 7/60 → v = +8.57 cm. m = −v/u = 0.43; h′ = 2.14 cm. ప్రతిబింబం దర్పణం వెనుక 8.6 cm, మిథ్యా, నిటారు, చిన్నది","15) h = 7 cm, u = −27 cm, f = −18 cm. 1/v = 1/f − 1/u = −1/18 + 1/27 = −1/54 → v = −54 cm. తెర దర్పణం ముందు 54 cm వద్ద ఉంచాలి. m = −v/u = −2 → h′ = −14 cm: నిజ, తలకిందులు, పెద్దది (14 cm)","16) f = 1/P = 1/(−2) = −0.5 m = −50 cm. పుటాకార (అపసారి) కటకం","17) f = 1/P = 1/1.5 = 0.67 m = 66.7 cm. P ధనం – అభిసారి (కుంభాకార) కటకం"]]],"by":"భౌతిక శాస్త్రం 10వ తరగతి (పుటలు 162–215)"},{"id":"ph10","no":10,"t":"మానవ నేత్రం, రంగుల ప్రపంచం (The Human Eye and the Colourful World)","m":[8],"ty":"Chapter 10","th":"కంటి నిర్మాణం, సర్దుబాటు, దృష్టి దోషాలు, పట్టకం ద్వారా వక్రీభవనం, విక్షేపణం, వాతావరణ వక్రీభవనం, కాంతి పరిక్షేపణం","sum":"మానవ నేత్రం కెమెరా లాంటిది: కార్నియా (శుక్లపటలం) ద్వారా కాంతి ప్రవేశిస్తుంది, కనుపాప (iris) తారక (pupil) పరిమాణాన్ని నియంత్రిస్తుంది, కటకం రెటీనా (నేత్రపటలం) పై తలకిందులు నిజ ప్రతిబింబం ఏర్పరుస్తుంది; దృష్టి నాడి సంకేతాలను మెదడుకు పంపుతుంది. సిలియరీ కండరాలు కటకం నాభ్యంతరాన్ని మార్చే సామర్థ్యం సర్దుబాటు (accommodation). సాధారణ కంటికి సమీప బిందువు 25 cm, దూర బిందువు అనంతం. దృష్టి దోషాలు: హ్రస్వదృష్టి (myopia – దూరం కనిపించదు, పుటాకార కటకం), దీర్ఘదృష్టి (hypermetropia – దగ్గర కనిపించదు, కుంభాకార కటకం), చత్వారం (presbyopia – వయసుతో, ద్విమితీయ కటకాలు). గాజు పట్టకంలో తెల్లని కాంతి ఏడు రంగులుగా (VIBGYOR) విడిపోవడం విక్షేపణం (dispersion) – ఇంద్రధనుస్సు కూడా అలాగే. వాతావరణ వక్రీభవనం వల్ల నక్షత్రాలు మిణుకుమిణుకుమంటాయి, సూర్యోదయం 2 నిమిషాలు ముందుగా, సూర్యాస్తమయం ఆలస్యంగా కనిపిస్తుంది. కాంతి పరిక్షేపణం (scattering) వల్ల ఆకాశం నీలం, సూర్యోదయ–అస్తమయాల్లో సూర్యుడు ఎర్రగా, టిండాల్ ప్రభావం.","pts":["కంటి భాగాలు: కార్నియా, కనుపాప (iris), తారక (pupil), కటకం, సిలియరీ కండరాలు, రెటీనా, దృష్టి నాడి.","కాంతి వక్రీభవనం ఎక్కువగా కార్నియా వద్దే జరుగుతుంది; కటకం నాభ్యంతరాన్ని సూక్ష్మంగా సర్దుబాటు చేస్తుంది.","సర్దుబాటు: దూరపు వస్తువుకు సిలియరీ కండరాలు సడలి కటకం పలుచబడుతుంది (f పెరుగుతుంది); దగ్గర వస్తువుకు సంకోచించి కటకం మందం (f తగ్గుతుంది).","స్పష్ట దృష్టి కనిష్ఠ దూరం (సమీప బిందువు) = 25 cm; దూర బిందువు = అనంతం.","హ్రస్వదృష్టి: ప్రతిబింబం రెటీనా ముందు; కారణాలు – కటకం అధిక వక్రత, కనుగుడ్డు పొడవు; నివారణ – పుటాకార కటకం.","దీర్ఘదృష్టి: ప్రతిబింబం రెటీనా వెనుక; కారణాలు – కటకం నాభ్యంతరం ఎక్కువ, కనుగుడ్డు చిన్నది; నివారణ – కుంభాకార కటకం.","చత్వారం: వయసుతో సిలియరీ కండరాలు బలహీనం; ద్విమితీయ (bifocal) కటకాలు. కంటిశుక్లం (cataract) – శస్త్రచికిత్స.","పట్టకం: విచలన కోణం; తెల్లని కాంతి VIBGYOR గా విక్షేపణం – ఎరుపు తక్కువ, ఊదా ఎక్కువ వంగుతుంది.","వాతావరణ వక్రీభవనం: నక్షత్రాలు మిణుకు మిణుకు; గ్రహాలు విస్తృత మూలాలు కాబట్టి మిణుకు మిణుకుమనవు; సూర్యోదయం ముందుగా కనిపిస్తుంది.","పరిక్షేపణం: చిన్న కణాలు నీలి (తక్కువ తరంగదైర్ఘ్యం) కాంతిని ఎక్కువగా పరిక్షేపిస్తాయి → ఆకాశం నీలం; వ్యోమగాములకు ఆకాశం నల్లగా (వాతావరణం లేదు)."],"w":[["నేత్రపటలం","Retina"],["శుక్లపటలం","Cornea"],["కనుపాప","Iris"],["తారక","Pupil"],["సర్దుబాటు","Power of accommodation"],["హ్రస్వదృష్టి","Myopia (near-sightedness)"],["దీర్ఘదృష్టి","Hypermetropia (far-sightedness)"],["చత్వారం","Presbyopia"],["విక్షేపణం","Dispersion"],["వర్ణపటం","Spectrum (VIBGYOR)"],["వాతావరణ వక్రీభవనం","Atmospheric refraction"],["కాంతి పరిక్షేపణం","Scattering of light"]],"gr":{"t":"సూత్రాలు & ముఖ్యాంశాలు","p":["P = 1/f (m);  హ్రస్వదృష్టి సవరణ కటకం f = −(దూర బిందువు)","దీర్ఘదృష్టి: u = −25 cm, v = −(సమీప బిందువు) → 1/f = 1/v − 1/u","ఉదా: దూర బిందువు 80 cm → f = −80 cm = −0.8 m → P = −1.25 D","ఉదా: సమీప బిందువు 1 m → 1/f = −1/100 + 1/25 = 3/100 → f = +33.3 cm, P = +3 D","VIBGYOR: Violet, Indigo, Blue, Green, Yellow, Orange, Red"]},"qa":[["కంటి సర్దుబాటు సామర్థ్యం అంటే?","కటకం నాభ్యంతరాన్ని మార్చుకుని దగ్గర, దూర వస్తువులను స్పష్టంగా చూడగల సామర్థ్యం."],["హ్రస్వదృష్టి ఉన్న వ్యక్తికి 1.2 m కి ఆవల కనిపించదు – ఏ కటకం?","పుటాకార (అపసారి) కటకం."],["సాధారణ కంటి సమీప, దూర బిందువులు?","25 cm, అనంతం."],["నక్షత్రాలు ఎందుకు మిణుకుమిణుకుమంటాయి?","వాతావరణ వక్రీభవనం వల్ల నక్షత్ర కాంతి మార్గం, ప్రకాశం నిరంతరం మారుతుంది."],["ఆకాశం నీలంగా ఎందుకు?","గాలి అణువులు నీలి (తక్కువ తరంగదైర్ఘ్యం) కాంతిని ఎక్కువగా పరిక్షేపిస్తాయి."],["సూర్యోదయంలో సూర్యుడు ఎర్రగా ఎందుకు?","కాంతి ఎక్కువ దూరం వాతావరణంలో ప్రయాణిస్తుంది; నీలి కాంతి పరిక్షేపణం చెందిపోయి ఎరుపు మాత్రమే మనకు చేరుతుంది."]],"act":"గాజు పట్టకం (లేదా అద్దం ఉంచిన నీటి గిన్నె) ద్వారా సూర్యకాంతిని గోడపై పడేలా చేసి VIBGYOR రంగులు చూడండి. చీకటి గదిలో టార్చ్ కాంతిని పొగ/దుమ్ము గుండా పంపి టిండాల్ ప్రభావం గమనించండి. పాఠశాలలో విద్యార్థుల సమీప బిందువు స్కేలుతో కొలవండి.","kn":"మరణానంతరం నేత్రదానం చేయవచ్చు – ఒక జత కళ్ళతో ఇద్దరికి చూపు (కార్నియా అంధత్వం). ప్రమాద సూచికలు (ట్రాఫిక్ సిగ్నల్ ఆపు దీపం) ఎరుపు రంగులో ఎందుకంటే ఎరుపు తక్కువ పరిక్షేపణం చెంది పొగమంచులో కూడా దూరం కనిపిస్తుంది.","qz":[["కంటిలో ప్రతిబింబం ఏర్పడేది?","రెటీనా","కార్నియా","కనుపాప","తారక"],["తారక పరిమాణాన్ని నియంత్రించేది?","కనుపాప (iris)","కార్నియా","రెటీనా","దృష్టి నాడి"],["కటకం నాభ్యంతరాన్ని మార్చేవి?","సిలియరీ కండరాలు","కనుపాప","కార్నియా","దృష్టి నాడి"],["స్పష్ట దృష్టి కనిష్ఠ దూరం?","25 cm","2.5 m","25 m","2.5 cm"],["హ్రస్వదృష్టి సవరణ?","పుటాకార కటకం","కుంభాకార కటకం","ద్విమితీయ కటకం","సమతల గాజు"],["దీర్ఘదృష్టిలో ప్రతిబింబం ఎక్కడ?","రెటీనా వెనుక","రెటీనా ముందు","రెటీనా మీద","కార్నియా మీద"],["వయసుతో వచ్చే దృష్టి దోషం?","చత్వారం","హ్రస్వదృష్టి","వర్ణాంధత్వం","కంటిశుక్లం మాత్రమే"],["తెల్లని కాంతి రంగులుగా విడిపోవడం?","విక్షేపణం","పరావర్తనం","పరిక్షేపణం","శోషణ"],["ఎక్కువగా వంగే రంగు?","ఊదా","ఎరుపు","పసుపు","ఆకుపచ్చ"],["ఇంద్రధనుస్సు ఏర్పడేది?","వర్షపు బిందువుల్లో విక్షేపణం, పరావర్తనం","మేఘాల నీడ","సూర్యుని రంగు","ధూళి కణాలు"],["నక్షత్రాలు మిణుకుమనడానికి కారణం?","వాతావరణ వక్రీభవనం","పరిక్షేపణం","విక్షేపణం","పరావర్తనం"],["గ్రహాలు మిణుకుమనవు ఎందుకు?","దగ్గరగా ఉండి విస్తృత మూలాలుగా ఉంటాయి","అవి వేడిగా ఉంటాయి","వాటికి కాంతి లేదు","అవి కదలవు"],["ఆకాశం నీలంగా కనిపించడానికి కారణం?","కాంతి పరిక్షేపణం","విక్షేపణం","వక్రీభవనం","పరావర్తనం"],["వ్యోమగామికి ఆకాశం?","నల్లగా","నీలంగా","ఎర్రగా","తెల్లగా"],["ప్రమాద సంకేతాలు ఎరుపు ఎందుకు?","ఎరుపు తక్కువ పరిక్షేపణం చెందుతుంది","ఎరుపు అందమైనది","ఎరుపు ఎక్కువ వంగుతుంది","ఎరుపు చౌక"],["P = −5.5 D కటకం f?","−0.182 m","−5.5 m","+0.182 m","−0.55 m"],["దూర బిందువు 80 cm – సవరణ కటకం సామర్థ్యం?","−1.25 D","+1.25 D","−0.8 D","−80 D"],["సూర్యోదయం ఎన్ని నిమిషాలు ముందుగా కనిపిస్తుంది?","సుమారు 2 నిమిషాలు","10 నిమిషాలు","అసలు కాదు","30 సెకన్లు"]],"wb":{"mis":"హ్రస్వదృష్టి = దగ్గరది కనిపిస్తుంది, దూరం కనిపించదు (పేరు చూసి తారుమారు చేయకండి). \"కంటిలో అత్యధిక వక్రీభవనం కటకంలో\" అనడం తప్పు – కార్నియా వద్ద. దూర వస్తువుకు సిలియరీ కండరాలు సడలుతాయి, సంకోచించవు. సవరణ కటకం లెక్కల్లో cm ను m లోకి మార్చి P కనుక్కోవాలి.","qz":[["కంటి నాభ్యంతరం మార్చుకునే సామర్థ్యం?","సర్దుబాటు","హ్రస్వదృష్టి","దీర్ఘదృష్టి","చత్వారం"],["కంటి ప్రతిబింబం ఏర్పడేది?","రెటీనా","కార్నియా","కనుపాప","తారక"],["యువకుడి స్పష్ట దృష్టి కనిష్ఠ దూరం?","25 cm","2.5 cm","25 m","2.5 m"],["కటకం నాభ్యంతరం మార్పుకు కారణం?","సిలియరీ కండరాలు","తారక","రెటీనా","కనుపాప"],["−5.5 D, +1.5 D కటకాల నాభ్యంతరాలు?","−0.182 m, +0.667 m","−5.5 m, 1.5 m","−18.2 m, 66.7 m","+0.182 m, −0.667 m"],["దూర బిందువు 80 cm – కటకం?","పుటాకార, −1.25 D","కుంభాకార, +1.25 D","పుటాకార, −0.8 D","కుంభాకార, +0.8 D"],["సమీప బిందువు 1 m – సవరణ కటకం?","కుంభాకార, +3 D","పుటాకార, −3 D","కుంభాకార, +1 D","పుటాకార, −1 D"],["25 cm కంటే దగ్గర స్పష్టంగా కనిపించకపోవడానికి?","కటకం నాభ్యంతరం ఒక పరిమితి కంటే తగ్గదు","రెటీనా దూరం మారుతుంది","కాంతి చాలదు","కనుపాప మూసుకుంటుంది"],["వస్తువు దూరం పెరిగితే కంటిలో ప్రతిబింబ దూరం?","మారదు (నాభ్యంతరం మారుతుంది)","పెరుగుతుంది","తగ్గుతుంది","సున్నా"],["వ్యోమగామికి ఆకాశం నల్లగా ఎందుకు?","వాతావరణం లేదు – పరిక్షేపణం లేదు","సూర్యుడు లేడు","చీకటి సమయం","కళ్ళద్దాల వల్ల"]],"pg":"216–235","f":"books/10/Class10_Physical_Science_Textbook.pdf","p":222,"lb":"పాఠ్యపుస్తకం","ws":["పాఠంలోని ప్రశ్నలు 1 (పుట 222) – 4 ప్రశ్నలు","అభ్యాసాలు – Exercises (పుట 234) – 12 ప్రశ్నలు"]},"tg":[["పాఠంలోని ప్రశ్నలు 1 (పుట 222)",["1) సిలియరీ కండరాల సహాయంతో కంటి కటకం తన నాభ్యంతరాన్ని (వక్రతను) మార్చుకుని దగ్గర, దూర వస్తువులను స్పష్టంగా చూడగల సామర్థ్యం","2) హ్రస్వదృష్టి – పుటాకార (అపసారి) కటకం; నాభ్యంతరం f = −1.2 m (P = −0.83 D)","3) దూర బిందువు: అనంతం; సమీప బిందువు: 25 cm","4) హ్రస్వదృష్టి (myopia) – దూరంలోని బోర్డు కనిపించదు. తగిన సామర్థ్యం గల పుటాకార కటకం కళ్ళద్దాలతో సరిచేయవచ్చు"]],["అభ్యాసాలు – Exercises (పుట 234)",["1) (c) సర్దుబాటు (accommodation)","2) (c) రెటీనా","3) (c) 25 cm","4) (c) సిలియరీ కండరాలు","5) (i) దూర దృష్టి: f = 1/P = 1/(−5.5) = −0.182 m (−18.2 cm, పుటాకార) (ii) దగ్గర దృష్టి: f = 1/1.5 = +0.667 m (+66.7 cm, కుంభాకార)","6) హ్రస్వదృష్టి సవరణకు పుటాకార కటకం; f = −(దూర బిందువు) = −80 cm = −0.8 m. P = 1/(−0.8) = −1.25 D","7) దీర్ఘదృష్టి: దగ్గర వస్తువు కాంతి కిరణాలు రెటీనా వెనుక కేంద్రీకరిస్తాయి; కుంభాకార కటకం కిరణాలను ముందుగా కలిపి రెటీనాపై ప్రతిబింబం ఏర్పరుస్తుంది (చిత్రం గీయండి). u = −25 cm, v = −100 cm (సమీప బిందువు 1 m): 1/f = 1/v − 1/u = −1/100 + 1/25 = 3/100 → f = +33.3 cm = 0.333 m, P = +3 D","8) కంటి కటకం నాభ్యంతరం ఒక కనిష్ఠ పరిమితి కంటే తగ్గదు (సిలియరీ కండరాలు అంతకంటే సంకోచించలేవు). 25 cm కంటే దగ్గర వస్తువు ప్రతిబింబం రెటీనా వెనుక ఏర్పడుతుంది – మసకగా కనిపిస్తుంది","9) కంటిలో ప్రతిబింబ దూరం (కటకం నుండి రెటీనా) మారదు; వస్తువు దూరం పెరిగితే సిలియరీ కండరాలు సడలి కటకం నాభ్యంతరం పెరుగుతుంది – ప్రతిబింబం రెటీనా మీదే ఏర్పడుతుంది","10) నక్షత్ర కాంతి భూ వాతావరణంలోకి వచ్చినప్పుడు నిరంతరం వక్రీభవనం చెందుతుంది. వాతావరణ పొరల సాంద్రత, ఉష్ణోగ్రతలు మారుతూ ఉండటం వల్ల నక్షత్రం కనిపించే స్థానం, కంటికి చేరే కాంతి పరిమాణం మారుతూ ఉంటాయి – మిణుకు మిణుకుమంటుంది (నక్షత్రాలు బిందు మూలాలు)","11) గ్రహాలు దగ్గరగా ఉండి విస్తృత మూలాలు – అనేక బిందు మూలాల సముదాయం. ఒక్కో బిందువు కాంతిలో మార్పులు సగటున రద్దవుతాయి – మొత్తం ప్రకాశం స్థిరంగా ఉంటుంది, మిణుకుమనవు","12) అంతరిక్షంలో వాతావరణం (గాలి అణువులు, కణాలు) లేదు – సూర్యకాంతి పరిక్షేపణం జరగదు. కాబట్టి ఆకాశం నల్లగా కనిపిస్తుంది"]]],"by":"భౌతిక శాస్త్రం 10వ తరగతి (పుటలు 216–235)"},{"id":"ph11","no":11,"t":"విద్యుత్ (Electricity)","m":[9],"ty":"Chapter 11","th":"విద్యుదావేశం, ప్రవాహం, పొటెన్షియల్ భేదం, ఓమ్ నియమం, నిరోధం–నిరోధకత, శ్రేణి–సమాంతర సంధానం, జౌల్ ఉష్ణ నియమం, విద్యుత్ సామర్థ్యం","sum":"ఒక బిందువు గుండా ప్రతి సెకనుకు ప్రవహించే ఆవేశం విద్యుత్ ప్రవాహం: I = Q/t, యూనిట్ ఆంపియర్ (A); 1 C = 6.25 × 10¹⁸ ఎలక్ట్రాన్ల ఆవేశం. ఒక యూనిట్ ఆవేశాన్ని ఒక బిందువు నుండి మరో బిందువుకు తరలించడానికి చేసే పని పొటెన్షియల్ భేదం V = W/Q, యూనిట్ వోల్ట్ (V). బ్యాటరీ/ఘటం పొటెన్షియల్ భేదాన్ని నిలుపుతుంది. అమ్మీటర్ శ్రేణిలో, వోల్ట్‌మీటర్ సమాంతరంగా కలపాలి. ఓమ్ నియమం: ఉష్ణోగ్రత స్థిరంగా ఉంటే V ∝ I, V = IR. నిరోధం R = ρl/A – పొడవుకు అనులోమం, వైశాల్యానికి విలోమం, పదార్థంపై ఆధారం; ρ నిరోధకత (Ω m). శ్రేణి సంధానం R = R₁ + R₂ + … (ఒకే ప్రవాహం); సమాంతర సంధానం 1/R = 1/R₁ + 1/R₂ + … (ఒకే వోల్టేజ్) – ఇళ్లలో సమాంతర సంధానం. జౌల్ ఉష్ణ నియమం H = I²Rt – హీటర్లు, ఇస్త్రీ పెట్టె, బల్బు, ఫ్యూజ్. విద్యుత్ సామర్థ్యం P = VI = I²R = V²/R (వాట్); వాణిజ్య శక్తి యూనిట్ 1 kWh = 3.6 × 10⁶ J.","pts":["I = Q/t; 1 A = 1 C/s; 1 C = 6.25 × 10¹⁸ ఎలక్ట్రాన్లు (e = 1.6 × 10⁻¹⁹ C).","V = W/Q; 1 V = 1 J/C. సాంప్రదాయ ప్రవాహ దిశ ధన ధ్రువం నుండి ఋణ ధ్రువానికి (ఎలక్ట్రాన్ల ప్రవాహానికి వ్యతిరేకం).","అమ్మీటర్ – శ్రేణిలో (తక్కువ నిరోధం); వోల్ట్‌మీటర్ – సమాంతరంగా (ఎక్కువ నిరోధం).","ఓమ్ నియమం V = IR; V–I గ్రాఫ్ మూలబిందువు గుండా సరళరేఖ; వాలు = R.","R = ρl/A; పొడవు రెట్టింపైతే R రెట్టింపు; వ్యాసం రెట్టింపైతే R నాలుగో వంతు.","లోహాలు, మిశ్రలోహాల నిరోధకత: మిశ్రలోహాలకు (నిక్రోమ్) ఎక్కువ – హీటర్లకు; రాగి, అల్యూమినియం తక్కువ – తీగలకు; టంగ్‌స్టన్ – బల్బు తంతువు.","శ్రేణి: R = R₁ + R₂ + R₃; ప్రవాహం అంతటా ఒకటే, వోల్టేజ్ పంచబడుతుంది.","సమాంతరం: 1/R = 1/R₁ + 1/R₂ + 1/R₃; వోల్టేజ్ ఒకటే, ప్రవాహం పంచబడుతుంది; మొత్తం నిరోధం అతి చిన్న నిరోధం కంటే తక్కువ.","H = I²Rt (జౌల్); P = VI = I²R = V²/R (వాట్); E = Pt.","1 kWh (ఒక యూనిట్) = 1000 W × 3600 s = 3.6 × 10⁶ J."],"w":[["విద్యుదావేశం","Electric charge (C)"],["విద్యుత్ ప్రవాహం","Electric current (A)"],["పొటెన్షియల్ భేదం","Potential difference (V)"],["నిరోధం","Resistance (Ω)"],["నిరోధకత","Resistivity (Ω m)"],["వలయం","Circuit"],["శ్రేణి సంధానం","Series connection"],["సమాంతర సంధానం","Parallel connection"],["అమ్మీటర్ / వోల్ట్‌మీటర్","Ammeter / Voltmeter"],["తాపన ఫలితం","Heating effect"],["విద్యుత్ సామర్థ్యం","Electric power (W)"],["ఫ్యూజ్","Fuse"]],"gr":{"t":"సూత్రాలు","p":["I = Q/t | V = W/Q | V = IR | R = ρl/A","శ్రేణి: R = R₁ + R₂ + R₃ | సమాంతరం: 1/R = 1/R₁ + 1/R₂ + 1/R₃","H = I²Rt = VIt | P = VI = I²R = V²/R | E = Pt","1 kWh = 3.6 × 10⁶ J","ఉదా: 220 V, 5 A మోటారు → P = 1100 W; 2 గంటల్లో E = 2.2 kWh = 7.92 × 10⁶ J."]},"qa":[["విద్యుత్ వలయం అంటే?","విద్యుత్ ప్రవాహం సాగే అవిచ్ఛిన్న, సంవృత మార్గం."],["1 C లో ఎన్ని ఎలక్ట్రాన్లు?","1/(1.6 × 10⁻¹⁹) = 6.25 × 10¹⁸."],["రెండు బిందువుల మధ్య పొటెన్షియల్ భేదం 1 V అంటే?","1 C ఆవేశాన్ని తరలించడానికి 1 J పని జరుగుతుంది."],["నిరోధం దేనిపై ఆధారపడుతుంది?","పొడవు, అడ్డుకోత వైశాల్యం, పదార్థం స్వభావం (ఉష్ణోగ్రత)."],["ఇళ్లలో సమాంతర సంధానం ఎందుకు?","ప్రతి ఉపకరణానికి పూర్తి వోల్టేజ్; ఒకటి పాడైనా మిగిలినవి పని చేస్తాయి; వేర్వేరు స్విచ్‌లు."],["హీటర్ తీగ ఎర్రబడుతుంది కానీ కార్డ్ ఎందుకు కాదు?","హీటర్ ఎలిమెంట్ నిరోధం చాలా ఎక్కువ – ఎక్కువ ఉష్ణం; కార్డ్ (రాగి) నిరోధం తక్కువ."]],"act":"టార్చ్ బల్బు, 1.5 V ఘటాలు, తీగలతో శ్రేణి మరియు సమాంతర వలయాలు కట్టండి – ఒక బల్బు తీసేస్తే మిగిలినవి వెలుగుతాయా గమనించండి. మీ ఇంటి విద్యుత్ బిల్లులో \"యూనిట్లు\" చూసి, ఇంట్లోని ఉపకరణాల వాట్‌లు × గంటలతో నెల వినియోగం అంచనా వేయండి.","kn":"ఓమ్ నియమాన్ని జర్మన్ శాస్త్రవేత్త జార్జ్ సైమన్ ఓమ్ (1827) కనుగొన్నాడు. LED బల్బులు పాత ఫిలమెంట్ బల్బుల కంటే దాదాపు 80–90% తక్కువ విద్యుత్ వాడుతాయి – ఎందుకంటే తక్కువ శక్తి ఉష్ణంగా వృథా అవుతుంది.","qz":[["విద్యుత్ ప్రవాహం యూనిట్?","ఆంపియర్","వోల్ట్","ఓమ్","వాట్"],["పొటెన్షియల్ భేదం కొలిచే సాధనం?","వోల్ట్‌మీటర్","అమ్మీటర్","గాల్వనోమీటర్","ఓమ్‌మీటర్"],["వోల్ట్‌మీటర్ ఎలా కలపాలి?","సమాంతరంగా","శ్రేణిలో","ఏదైనా","కలపకూడదు"],["ఓమ్ నియమం?","V = IR","P = VI","H = I²Rt","R = ρl/A"],["1 C ఆవేశంలో ఎలక్ట్రాన్లు?","6.25 × 10¹⁸","1.6 × 10⁻¹⁹","6.25 × 10¹⁹","10¹⁸"],["తీగ పొడవు రెట్టింపైతే నిరోధం?","రెట్టింపు","సగం","నాలుగు రెట్లు","మారదు"],["తీగ వ్యాసం రెట్టింపైతే నిరోధం?","నాలుగో వంతు","సగం","రెట్టింపు","మారదు"],["నిరోధకత యూనిట్?","ఓమ్ మీటర్ (Ω m)","ఓమ్","ఓమ్/మీటర్","వోల్ట్"],["హీటర్ కాయిల్‌కు వాడే మిశ్రలోహం?","నిక్రోమ్","రాగి","అల్యూమినియం","వెండి"],["బల్బు తంతువు?","టంగ్‌స్టన్","రాగి","నిక్రోమ్","ఇనుము"],["2 Ω, 3 Ω, 6 Ω సమాంతరంగా?","1 Ω","11 Ω","2 Ω","0.5 Ω"],["4, 8, 12, 24 Ω లతో అత్యధిక నిరోధం?","48 Ω","24 Ω","2 Ω","12 Ω"],["P = ?","VI","V/I","I/V","IR²"],["1 kWh = ?","3.6 × 10⁶ J","3600 J","1000 J","3.6 × 10³ J"],["220 V, 5 A మోటారు సామర్థ్యం?","1100 W","44 W","225 W","2200 W"],["20 Ω ఇస్త్రీ పెట్టె, 5 A, 30 s – ఉష్ణం?","15000 J","3000 J","500 J","150 J"],["విద్యుత్ ప్రవాహం సాంప్రదాయ దిశ?","ధన ధ్రువం నుండి ఋణ ధ్రువానికి","ఋణం నుండి ధనానికి","రెండు దిశల్లో","దిశ లేదు"],["ఇళ్లలో వలయాలు?","సమాంతర సంధానం","శ్రేణి సంధానం","రెండూ కావు","శ్రేణి మాత్రమే"]],"wb":{"mis":"సమాంతర సంధానంలో 1/R కనుక్కొని దాన్నే R గా రాయడం సాధారణ తప్పు – చివర వ్యుత్క్రమం తీసుకోవాలి. mA ను A లోకి (÷1000), mm ను m లోకి మార్చాలి. 220 V, 100 W బల్బు 110 V లో 50 W కాదు – P = V²/R కాబట్టి 25 W. వోల్ట్‌మీటర్ శ్రేణిలో పెట్టకూడదు.","qz":[["R నిరోధం తీగను 5 సమ భాగాలు చేసి సమాంతరంగా కలిపితే R/R′ = ?","25","5","1/25","1/5"],["విద్యుత్ సామర్థ్యాన్ని సూచించనిది?","IR²","I²R","VI","V²/R"],["220 V–100 W బల్బు 110 V లో సామర్థ్యం?","25 W","50 W","75 W","100 W"],["సమాన తీగలు శ్రేణి, సమాంతరంలో – ఉష్ణం నిష్పత్తి?","1 : 4","1 : 2","2 : 1","4 : 1"],["12 V బ్యాటరీ, 2.5 mA ప్రవాహం – నిరోధం?","4800 Ω","30 Ω","4.8 Ω","480 Ω"],["9 V, 0.2 + 0.3 + 0.4 + 0.5 + 12 Ω శ్రేణి – ప్రవాహం?","0.67 A","0.75 A","1.5 A","0.5 A"],["220 V లో 5 A కోసం సమాంతర 176 Ω నిరోధాలు?","4","5","2","8"],["220 V, 10 W బల్బులు, గరిష్ఠ 5 A – ఎన్ని?","110","22","50","220"],["250 W TV 1 గం., 1200 W టోస్టర్ 10 ని. – ఎక్కువ శక్తి?","TV (250 Wh > 200 Wh)","టోస్టర్","రెండూ సమానం","చెప్పలేం"],["8 Ω హీటర్ 15 A – ఉష్ణ రేటు?","1800 W","120 W","960 W","14400 W"]],"pg":"236–283","f":"books/10/Class10_Physical_Science_Textbook.pdf","p":242,"lb":"పాఠ్యపుస్తకం","ws":["పాఠంలోని ప్రశ్నలు 1 (పుట 238) – 3 ప్రశ్నలు","పాఠంలోని ప్రశ్నలు 2 (పుట 242) – 3 ప్రశ్నలు","పాఠంలోని ప్రశ్నలు 3 (పుట 256) – 5 ప్రశ్నలు","పాఠంలోని ప్రశ్నలు 4 (పుట 264) – 2 ప్రశ్నలు","పాఠంలోని ప్రశ్నలు 5 (పుట 270) – 5 ప్రశ్నలు","పాఠంలోని ప్రశ్నలు 6 (పుట 274) – 3 ప్రశ్నలు","పాఠంలోని ప్రశ్నలు 7 (పుట 278) – 2 ప్రశ్నలు","అభ్యాసాలు – Exercises (పుట 280) – 18 ప్రశ్నలు"]},"tg":[["పాఠంలోని ప్రశ్నలు 1 (పుట 238)",["1) విద్యుత్ ప్రవాహం సాగే అవిచ్ఛిన్నమైన, సంవృత (మూసిన) మార్గాన్ని విద్యుత్ వలయం అంటారు","2) ఒక వాహకం గుండా ఒక సెకనులో 1 కూలుంబ్ ఆవేశం ప్రవహిస్తే ప్రవాహం 1 ఆంపియర్ (1 A = 1 C/s)","3) ఒక ఎలక్ట్రాన్ ఆవేశం 1.6 × 10⁻¹⁹ C. 1 C కి ఎలక్ట్రాన్లు = 1/(1.6 × 10⁻¹⁹) = 6.25 × 10¹⁸"]],["పాఠంలోని ప్రశ్నలు 2 (పుట 242)",["1) బ్యాటరీ / విద్యుత్ ఘటం (cell)","2) 1 C ఆవేశాన్ని ఒక బిందువు నుండి మరో బిందువుకు తరలించడానికి 1 J పని చేయాలి","3) W = VQ = 6 V × 1 C = 6 J"]],["పాఠంలోని ప్రశ్నలు 3 (పుట 256)",["1) వాహకం పొడవు (l), అడ్డుకోత వైశాల్యం (A), పదార్థం స్వభావం (ρ) – R = ρl/A (ఉష్ణోగ్రత కూడా)","2) మందమైన తీగ గుండా – అడ్డుకోత వైశాల్యం ఎక్కువ, నిరోధం తక్కువ","3) I = V/R; V సగమైతే I కూడా సగం అవుతుంది","4) మిశ్రలోహాలకు నిరోధకత ఎక్కువ, అధిక ఉష్ణోగ్రత వద్ద కూడా ఆక్సీకరణం చెంది మండిపోవు – ఎక్కువ ఉష్ణం ఇస్తాయి","5) (a) ఇనుము మంచి వాహకం (ఇనుము ρ = 10.0 × 10⁻⁸, పాదరసం 94.0 × 10⁻⁸ Ω m) (b) వెండి ఉత్తమ వాహకం (ρ = 1.60 × 10⁻⁸ Ω m)"]],["పాఠంలోని ప్రశ్నలు 4 (పుట 264)",["1) మూడు 2 V ఘటాల బ్యాటరీ (మొత్తం 6 V), 5 Ω, 8 Ω, 12 Ω నిరోధాలు, ప్లగ్ కీ – అన్నీ ఒకే వరుసలో (శ్రేణిలో) కలిపిన వలయ చిత్రం గీయాలి","2) అదే వలయంలో అమ్మీటర్‌ను శ్రేణిలో, వోల్ట్‌మీటర్‌ను 12 Ω నిరోధానికి సమాంతరంగా కలపాలి. రీడింగులు: R = 25 Ω, I = 6/25 = 0.24 A; 12 Ω పై V = 0.24 × 12 = 2.88 V"]],["పాఠంలోని ప్రశ్నలు 5 (పుట 270)",["1) (a) 1 Ω, 10⁶ Ω సమాంతరంగా – సుమారు 1 Ω (కొద్దిగా తక్కువ) (b) 1 Ω, 10³ Ω, 10⁶ Ω – సుమారు 1 Ω (కనిష్ఠ నిరోధం కంటే తక్కువ)","2) 1/R = 1/100 + 1/50 + 1/500 = 16/500 → R = 31.25 Ω. మొత్తం ప్రవాహం I = 220/31.25 = 7.04 A. అంతే ప్రవాహం తీసుకునే ఇస్త్రీ పెట్టె నిరోధం = 31.25 Ω, ప్రవాహం 7.04 A","3) ప్రతి ఉపకరణానికి పూర్తి వోల్టేజ్ అందుతుంది; ఒకటి పాడైనా మిగిలినవి పని చేస్తాయి; వేర్వేరు స్విచ్‌లు; మొత్తం నిరోధం తక్కువ, అవసరమైన ప్రవాహం తీసుకుంటాయి","4) (a) 4 Ω: 3 Ω, 6 Ω సమాంతరం (2 Ω) + 2 Ω శ్రేణిలో (b) 1 Ω: మూడింటినీ సమాంతరంగా (1/R = 1/2 + 1/3 + 1/6 = 1)","5) (a) అత్యధికం – శ్రేణి: 4 + 8 + 12 + 24 = 48 Ω (b) అత్యల్పం – సమాంతరం: 1/R = 1/4 + 1/8 + 1/12 + 1/24 = 12/24 → R = 2 Ω"]],["పాఠంలోని ప్రశ్నలు 6 (పుట 274)",["1) హీటింగ్ ఎలిమెంట్ (నిక్రోమ్) నిరోధం చాలా ఎక్కువ – I²Rt ఉష్ణం ఎక్కువై ఎర్రబడుతుంది; కార్డ్ (రాగి) నిరోధం చాలా తక్కువ – ఉష్ణం తక్కువ","2) H = VQ = 50 V × 96000 C = 4.8 × 10⁶ J (ఒక గంటలో)","3) H = I²Rt = 5² × 20 × 30 = 15000 J = 1.5 × 10⁴ J"]],["పాఠంలోని ప్రశ్నలు 7 (పుట 278)",["1) విద్యుత్ సామర్థ్యం (power) – P = VI","2) P = VI = 220 × 5 = 1100 W. 2 గంటల్లో E = 1100 × 7200 = 7.92 × 10⁶ J (= 2.2 kWh)"]],["అభ్యాసాలు – Exercises (పుట 280)",["1) (d) 25 – ఒక్కో భాగం R/5; ఐదు సమాంతరంగా R′ = (R/5)/5 = R/25 → R/R′ = 25","2) (b) IR²","3) (d) 25 W – R = V²/P = 220²/100 = 484 Ω; 110 V లో P = 110²/484 = 25 W","4) (c) 1 : 4 – శ్రేణి 2R, సమాంతరం R/2; H = V²t/R → H_s : H_p = (1/2R) : (2/R) = 1 : 4","5) వోల్ట్‌మీటర్‌ను ఆ రెండు బిందువుల మధ్య సమాంతరంగా కలపాలి","6) A = πd²/4 = 3.14 × (0.5 × 10⁻³)²/4 = 1.96 × 10⁻⁷ m². l = RA/ρ = 10 × 1.96 × 10⁻⁷ / 1.6 × 10⁻⁸ ≈ 122.7 m. వ్యాసం రెట్టింపైతే A నాలుగు రెట్లు → R = 10/4 = 2.5 Ω (నాలుగో వంతు)","7) V–I గ్రాఫ్ మూలబిందువు గుండా సరళరేఖ. వాలు R = V/I ≈ 13.2/4 ≈ 3.3–3.4 Ω (సుమారు 3.4 Ω)","8) R = V/I = 12 / (2.5 × 10⁻³) = 4800 Ω = 4.8 kΩ","9) మొత్తం R = 0.2 + 0.3 + 0.4 + 0.5 + 12 = 13.4 Ω. I = 9/13.4 ≈ 0.67 A (శ్రేణిలో అన్నింటి గుండా ఒకటే – 12 Ω గుండా కూడా 0.67 A)","10) అవసరమైన R = V/I = 220/5 = 44 Ω. n సమాంతర 176 Ω: 176/n = 44 → n = 4","11) (i) 9 Ω: రెండు 6 Ω సమాంతరం (3 Ω) + మూడో 6 Ω శ్రేణిలో → 9 Ω (ii) 4 Ω: రెండు 6 Ω శ్రేణిలో (12 Ω), దానికి మూడో 6 Ω సమాంతరంగా → 12 × 6/18 = 4 Ω","12) ఒక బల్బు ప్రవాహం = P/V = 10/220 A. బల్బుల సంఖ్య = 5 ÷ (10/220) = 110 (లేదా ఒక్కో బల్బు R = 4840 Ω, మొత్తం 44 Ω కావాలి → n = 110)","13) (i) విడిగా: I = 220/24 ≈ 9.17 A (ii) శ్రేణి: R = 48 Ω, I = 220/48 ≈ 4.58 A (iii) సమాంతరం: R = 12 Ω, I = 220/12 ≈ 18.33 A","14) (i) I = 6/(1 + 2) = 2 A; 2 Ω లో P = I²R = 4 × 2 = 8 W (ii) సమాంతరంలో 2 Ω పై 4 V: P = V²/R = 16/2 = 8 W. రెండు సందర్భాల్లోనూ సమానం – 8 W","15) I₁ = 100/220, I₂ = 60/220; మొత్తం I = 160/220 ≈ 0.73 A","16) TV: 250 W × 1 h = 250 Wh; టోస్టర్: 1200 W × (10/60) h = 200 Wh. TV ఎక్కువ శక్తి వాడుతుంది","17) ఉష్ణ రేటు = P = I²R = 15² × 8 = 1800 W (1.8 kW); 2 గంటల్లో 3.6 kWh = 1.296 × 10⁷ J","18) (a) టంగ్‌స్టన్ ద్రవీభవన స్థానం చాలా ఎక్కువ (3380 °C), నిరోధకత ఎక్కువ – వేడెక్కి కాంతిని ఇస్తూ కరిగిపోదు (b) మిశ్రలోహాలకు నిరోధకత ఎక్కువ, అధిక ఉష్ణోగ్రత వద్ద ఆక్సీకరణం (మండటం) చెందవు (c) శ్రేణిలో ఒకటి పాడైతే అన్నీ ఆగిపోతాయి; అన్నింటి గుండా ఒకే ప్రవాహం – వేర్వేరు ఉపకరణాలకు సరిపోదు; మొత్తం నిరోధం ఎక్కువ (d) R = ρl/A – అడ్డుకోత వైశాల్యం పెరిగితే నిరోధం తగ్గుతుంది (విలోమానుపాతం) (e) రాగి, అల్యూమినియం నిరోధకత తక్కువ, మంచి వాహకాలు – ప్రసారంలో ఉష్ణ నష్టం తక్కువ; అల్యూమినియం తేలిక, చౌక"]]],"by":"భౌతిక శాస్త్రం 10వ తరగతి (పుటలు 236–283)"},{"id":"ph12","no":12,"t":"విద్యుత్ ప్రవాహ అయస్కాంత ఫలితాలు (Magnetic Effects of Electric Current)","m":[11],"ty":"Chapter 12","th":"అయస్కాంత క్షేత్రం, క్షేత్ర రేఖలు, తీగ–వలయం–సోలినాయిడ్ చుట్టూ క్షేత్రం, ప్రవాహ వాహకంపై బలం, ఇంటి విద్యుత్ వలయాలు","sum":"విద్యుత్ ప్రవాహం అయస్కాంత క్షేత్రాన్ని ఏర్పరుస్తుంది (ఆర్‌స్టెడ్, 1820) – ప్రవాహం ఉన్న తీగ దగ్గర దిక్సూచి సూచీ విచలనం చెందుతుంది. అయస్కాంత క్షేత్రం దిశ, పరిమాణం కలది; క్షేత్ర రేఖలు అయస్కాంతం బయట ఉత్తర ధ్రువం నుండి దక్షిణ ధ్రువానికి, లోపల దక్షిణం నుండి ఉత్తరానికి – సంవృత వక్రాలు, ఎప్పుడూ ఖండించుకోవు; దగ్గరగా ఉన్నచోట క్షేత్రం బలమైనది. సరళ తీగ చుట్టూ క్షేత్ర రేఖలు ఏకకేంద్ర వృత్తాలు – దిశను కుడిచేతి బొటనవేలు నియమం చెబుతుంది. వృత్తాకార వలయం మధ్యలో క్షేత్రం దాదాపు సరళరేఖ; సోలినాయిడ్ లోపల క్షేత్రం ఏకరీతి – మెత్తని ఇనుప కడ్డీ పెడితే విద్యుదయస్కాంతం. అయస్కాంత క్షేత్రంలో ప్రవాహ వాహకంపై బలం (ఆంపియర్) – క్షేత్రానికి లంబంగా ఉన్నప్పుడు గరిష్ఠం; దిశను ఫ్లెమింగ్ ఎడమచేతి నియమం చెబుతుంది (మోటారు, MRI). ఇంటి వలయాలు: లైవ్ (ఎరుపు), న్యూట్రల్ (నలుపు), ఎర్త్ (ఆకుపచ్చ) తీగలు, 220 V, 50 Hz; ఫ్యూజ్, MCB, ఎర్తింగ్ భద్రత కోసం; షార్ట్ సర్క్యూట్, ఓవర్‌లోడింగ్ ప్రమాదాలు.","pts":["ఆర్‌స్టెడ్ ప్రయోగం: ప్రవాహ తీగ దగ్గర దిక్సూచి సూచీ కదులుతుంది – విద్యుత్, అయస్కాంతత్వం సంబంధం.","క్షేత్ర రేఖలు: బయట N → S, లోపల S → N; సంవృత వక్రాలు; ఖండించుకోవు (ఒకే బిందువు వద్ద రెండు దిశలు ఉండవు); దగ్గరగా = బలమైన క్షేత్రం.","సరళ తీగ: ఏకకేంద్ర వృత్తాలు; ప్రవాహం పెరిగితే క్షేత్రం పెరుగుతుంది, దూరం పెరిగితే తగ్గుతుంది.","కుడిచేతి బొటనవేలు నియమం: బొటనవేలు ప్రవాహ దిశలో ఉంటే మడిచిన వేళ్ళు క్షేత్ర దిశను చూపుతాయి.","వృత్తాకార వలయం: మధ్యలో క్షేత్రం సరళరేఖ; చుట్ల సంఖ్య n పెరిగితే క్షేత్రం n రెట్లు.","సోలినాయిడ్: లోపల ఏకరీతి క్షేత్రం (సమాంతర రేఖలు) – దండాయస్కాంతం లాంటిది; ఇనుప కోర్‌తో విద్యుదయస్కాంతం.","ప్రవాహ వాహకంపై బలం: ప్రవాహం, క్షేత్రం ఒకదానికొకటి లంబంగా ఉన్నప్పుడు గరిష్ఠం; ప్రవాహం/క్షేత్ర దిశ మారితే బల దిశ మారుతుంది.","ఫ్లెమింగ్ ఎడమచేతి నియమం: చూపుడు వేలు – క్షేత్రం, మధ్య వేలు – ప్రవాహం, బొటనవేలు – బలం (చలనం).","ఇంటి వలయం: లైవ్ (ఎరుపు) – 220 V, న్యూట్రల్ (నలుపు) – 0 V, ఎర్త్ (ఆకుపచ్చ); 15 A (ఎక్కువ సామర్థ్య ఉపకరణాలు), 5 A (బల్బులు, ఫ్యాన్లు) వలయాలు.","షార్ట్ సర్క్యూట్: లైవ్, న్యూట్రల్ నేరుగా తాకితే ప్రవాహం చాలా పెరుగుతుంది; ఓవర్‌లోడింగ్: ఒకే సాకెట్‌కు ఎక్కువ ఉపకరణాలు – ఫ్యూజ్ కరిగి వలయాన్ని తెంచుతుంది."],"w":[["అయస్కాంత క్షేత్రం","Magnetic field"],["క్షేత్ర రేఖలు","Field lines"],["దిక్సూచి","Compass"],["సోలినాయిడ్","Solenoid"],["విద్యుదయస్కాంతం","Electromagnet"],["కుడిచేతి బొటనవేలు నియమం","Right-hand thumb rule"],["ఫ్లెమింగ్ ఎడమచేతి నియమం","Fleming’s left-hand rule"],["లైవ్ తీగ","Live wire"],["న్యూట్రల్ తీగ","Neutral wire"],["భూ సంధానం","Earthing"],["లఘు వలయం","Short circuit"],["అధిక భారం","Overloading"]],"gr":{"t":"ముఖ్య నియమాలు","p":["కుడిచేతి బొటనవేలు నియమం → తీగ చుట్టూ క్షేత్ర దిశ","ఫ్లెమింగ్ ఎడమచేతి నియమం → ప్రవాహ వాహకంపై బల దిశ (మోటారు)","ఫ్లెమింగ్ కుడిచేతి నియమం → ప్రేరిత ప్రవాహ దిశ (జనరేటర్)","P = VI → 2 kW ఓవెన్ 220 V లో I = 2000/220 ≈ 9 A (5 A వలయంలో ఫ్యూజ్ కరుగుతుంది)","రంగులు: లైవ్ – ఎరుపు, న్యూట్రల్ – నలుపు, ఎర్త్ – ఆకుపచ్చ"]},"qa":[["రెండు క్షేత్ర రేఖలు ఎందుకు ఖండించుకోవు?","ఖండిస్తే ఆ బిందువు వద్ద దిక్సూచి రెండు దిశలు చూపాలి – అసాధ్యం."],["టేబుల్‌పై వలయంలో సవ్యదిశ ప్రవాహం – క్షేత్రం?","వలయం లోపల టేబుల్‌లోకి (కిందికి), బయట టేబుల్ నుండి పైకి."],["ఏకరీతి అయస్కాంత క్షేత్రాన్ని ఎలా చూపుతాం?","సమాన దూరంలో ఉన్న సమాంతర సరళరేఖలతో."],["స్వేచ్ఛగా కదిలే ప్రోటాన్ ఏ ధర్మాలు మారవచ్చు?","వేగం దిశ (velocity), ద్రవ్యవేగం (momentum)."],["ఎర్త్ తీగ ఉపయోగం?","లోహ ఉపకరణం బయటి భాగానికి లీక్ అయిన ప్రవాహాన్ని భూమిలోకి పంపి షాక్ నుండి కాపాడుతుంది."],["ఓవర్‌లోడింగ్ ఎలా నివారిస్తాం?","ఒకే సాకెట్‌కు ఎక్కువ ఉపకరణాలు కలపకూడదు; సరైన రేటింగ్ ఫ్యూజ్/MCB."]],"act":"దండాయస్కాంతం పై కాగితం పెట్టి ఇనుప రజను చల్లి మెల్లగా తట్టండి – క్షేత్ర రేఖల నమూనా చూడండి. ఇనుప మేకుకు ఇన్సులేటెడ్ రాగి తీగ 50 చుట్లు చుట్టి 3 V బ్యాటరీతో కలిపి గుండు సూదులను ఆకర్షించే విద్యుదయస్కాంతం తయారు చేయండి.","kn":"మన గుండె, మెదడులో నాడీ ప్రవాహాలు కూడా చాలా బలహీనమైన అయస్కాంత క్షేత్రాలు ఏర్పరుస్తాయి – MRI (Magnetic Resonance Imaging) దీని ఆధారంగానే శరీర భాగాల చిత్రాలు తీస్తుంది. మాగ్లెవ్ రైళ్లు విద్యుదయస్కాంతాలతో పట్టాలపై తేలుతూ నడుస్తాయి.","qz":[["విద్యుత్ ప్రవాహం అయస్కాంత క్షేత్రం ఏర్పరుస్తుందని కనుగొన్నది?","ఆర్‌స్టెడ్","ఫారడే","ఓమ్","న్యూటన్"],["అయస్కాంతం బయట క్షేత్ర రేఖల దిశ?","ఉత్తరం నుండి దక్షిణం","దక్షిణం నుండి ఉత్తరం","రెండు వైపులా","దిశ లేదు"],["క్షేత్ర రేఖలు దగ్గరగా ఉన్నచోట క్షేత్రం?","బలమైనది","బలహీనమైనది","సున్నా","ఏకరీతి"],["సరళ తీగ చుట్టూ క్షేత్ర రేఖలు?","ఏకకేంద్ర వృత్తాలు","సమాంతర రేఖలు","వ్యాసార్ధ రేఖలు","దీర్ఘవృత్తాలు"],["సోలినాయిడ్ లోపల క్షేత్రం?","అన్ని బిందువుల వద్ద ఒకటే","సున్నా","చివర్ల వైపు పెరుగుతుంది","చివర్ల వైపు తగ్గుతుంది"],["విద్యుదయస్కాంతం కోర్?","మెత్తని ఇనుము","రాగి","అల్యూమినియం","ఉక్కు మాత్రమే"],["ప్రవాహ వాహకంపై బలం గరిష్ఠం ఎప్పుడు?","ప్రవాహం క్షేత్రానికి లంబంగా ఉన్నప్పుడు","సమాంతరంగా ఉన్నప్పుడు","45° వద్ద","ప్రవాహం సున్నా"],["ఫ్లెమింగ్ ఎడమచేతి నియమంలో బొటనవేలు?","బలం/చలనం","క్షేత్రం","ప్రవాహం","వోల్టేజ్"],["తీగ చుట్టూ క్షేత్ర దిశ నియమం?","కుడిచేతి బొటనవేలు నియమం","ఫ్లెమింగ్ ఎడమచేతి","లెంజ్ నియమం","ఓమ్ నియమం"],["లైవ్ తీగ రంగు?","ఎరుపు","ఆకుపచ్చ","నలుపు","నీలం"],["ఎర్త్ తీగ రంగు?","ఆకుపచ్చ","ఎరుపు","నలుపు","పసుపు"],["భారతదేశంలో గృహ వోల్టేజ్?","220 V","110 V","440 V","12 V"],["షార్ట్ సర్క్యూట్‌లో ప్రవాహం?","అతిగా పెరుగుతుంది","తగ్గుతుంది","మారదు","సున్నా"],["ఫ్యూజ్ పని చేసే సూత్రం?","జౌల్ ఉష్ణ ఫలితం","అయస్కాంత ఫలితం","రసాయన ఫలితం","కాంతి ఫలితం"],["పశ్చిమానికి వెళ్ళే ఆల్ఫా కణం ఉత్తరానికి విచలనం – క్షేత్రం?","పైకి (upward)","కిందికి","దక్షిణం","తూర్పు"],["అయస్కాంత క్షేత్రంలో ప్రోటాన్ ద్రవ్యరాశి?","మారదు","పెరుగుతుంది","తగ్గుతుంది","సున్నా"],["జనరేటర్ ప్రేరిత ప్రవాహ దిశ నియమం?","ఫ్లెమింగ్ కుడిచేతి నియమం","ఫ్లెమింగ్ ఎడమచేతి నియమం","కుడిచేతి బొటనవేలు","ఓమ్ నియమం"],["MRI లో వాడేది?","అయస్కాంతత్వం","X-కిరణాలు మాత్రమే","శబ్దం","రేడియోధార్మికత"]],"wb":{"mis":"ఫ్లెమింగ్ ఎడమచేతి నియమం (మోటారు – బలం) మరియు కుడిచేతి నియమం (జనరేటర్ – ప్రేరిత ప్రవాహం) తారుమారు చేయకూడదు. ఎలక్ట్రాన్ ప్రవాహ దిశ సాంప్రదాయ ప్రవాహానికి వ్యతిరేకం – ఎలక్ట్రాన్ పుంజం లెక్కల్లో ఇది గుర్తుంచుకోండి. ఆకుపచ్చ తీగ లైవ్ కాదు – ఎర్త్.","qz":[["సరళ తీగ దగ్గర అయస్కాంత క్షేత్రం?","తీగ కేంద్రంగా ఏకకేంద్ర వృత్తాలు","తీగకు లంబ సరళరేఖలు","తీగకు సమాంతర రేఖలు","వ్యాసార్ధ రేఖలు"],["షార్ట్ సర్క్యూట్ సమయంలో ప్రవాహం?","అతిగా పెరుగుతుంది","చాలా తగ్గుతుంది","మారదు","నిరంతరం మారుతుంది"],["\"పొడవైన వృత్తాకార కాయిల్ మధ్య క్షేత్రం సమాంతర రేఖలు\" – ?","ఒప్పు","తప్పు","కొంత ఒప్పు","చెప్పలేం"],["\"ఆకుపచ్చ తీగ సాధారణంగా లైవ్ తీగ\" – ?","తప్పు","ఒప్పు","కొన్నిసార్లు","చెప్పలేం"],["అయస్కాంత క్షేత్రం ఏర్పరిచే రెండు పద్ధతులు?","శాశ్వత అయస్కాంతం, ప్రవాహ వాహకం (విద్యుదయస్కాంతం)","ఘర్షణ, ఉష్ణం","కాంతి, శబ్దం","నీరు, గాలి"],["ఎలక్ట్రాన్ పుంజం వెనుక గోడ నుండి ముందుకు, కుడివైపు విచలనం – క్షేత్ర దిశ?","నిలువుగా కిందికి","నిలువుగా పైకి","ముందుకు","ఎడమకు"],["షార్ట్ సర్క్యూట్ ఎప్పుడు?","లైవ్, న్యూట్రల్ తీగలు నేరుగా తాకినప్పుడు","ఫ్యూజ్ కరిగినప్పుడు","బల్బు ఆరిపోయినప్పుడు","ఎర్త్ తీగ ఉన్నప్పుడు"],["లోహ ఉపకరణాలను ఎర్త్ చేయడం ఎందుకు?","లీకైన ప్రవాహం భూమిలోకి – షాక్ నుండి రక్షణ","విద్యుత్ ఆదా","ఉపకరణం వేగం పెంచడానికి","శబ్దం తగ్గించడానికి"],["2 kW ఓవెన్, 220 V, 5 A రేటింగ్ వలయం – ఫలితం?","ఫ్యూజ్ కరుగుతుంది (≈9 A)","సాధారణంగా పని చేస్తుంది","ఓవెన్ వేడెక్కదు","వోల్టేజ్ పెరుగుతుంది"],["రాడ్ AB ప్రవాహం పెరిగితే స్థానభ్రంశం?","పెరుగుతుంది","తగ్గుతుంది","మారదు","దిశ మారుతుంది"]],"pg":"284–311","f":"books/10/Class10_Physical_Science_Textbook.pdf","p":290,"lb":"పాఠ్యపుస్తకం","ws":["పాఠంలోని ప్రశ్నలు 1 (పుట 294) – 3 ప్రశ్నలు","పాఠంలోని ప్రశ్నలు 2 (పుట 296) – 3 ప్రశ్నలు","పాఠంలోని ప్రశ్నలు 3 (పుట 300) – 3 ప్రశ్నలు","పాఠంలోని ప్రశ్నలు 4 (పుట 304) – 3 ప్రశ్నలు","అభ్యాసాలు – Exercises (పుట 308) – 9 ప్రశ్నలు"]},"tg":[["పాఠంలోని ప్రశ్నలు 1 (పుట 294)",["1) దండాయస్కాంతం చుట్టూ క్షేత్ర రేఖలు: బయట N నుండి S కు వంపు రేఖలు, లోపల S నుండి N కు; ధ్రువాల వద్ద దగ్గరగా (చిత్రం గీయాలి)","2) (i) బయట ఉత్తర ధ్రువం నుండి దక్షిణ ధ్రువానికి, లోపల దక్షిణం నుండి ఉత్తరానికి – సంవృత వక్రాలు (ii) దగ్గరగా ఉన్నచోట క్షేత్రం బలమైనది (iii) రెండు రేఖలు ఎప్పుడూ ఖండించుకోవు (iv) ఏ బిందువు వద్దనైనా స్పర్శరేఖ క్షేత్ర దిశ","3) ఖండిస్తే ఆ బిందువు వద్ద దిక్సూచి సూచీ రెండు దిశలను చూపాలి – అది అసాధ్యం"]],["పాఠంలోని ప్రశ్నలు 2 (పుట 296)",["1) కుడిచేతి బొటనవేలు నియమం ప్రకారం: సవ్యదిశ ప్రవాహానికి వలయం లోపల క్షేత్రం టేబుల్ తలానికి లంబంగా కిందికి (టేబుల్‌లోకి), బయట టేబుల్ నుండి పైకి","2) సమాన దూరంలో ఉన్న సమాంతర సరళరేఖలతో (ఒకే దిశలో బాణాలు) చూపాలి","3) (d) సోలినాయిడ్ లోపల అన్ని బిందువుల వద్ద క్షేత్రం ఒకటే (ఏకరీతి)"]],["పాఠంలోని ప్రశ్నలు 3 (పుట 300)",["1) (c) వేగం (velocity – దిశ మారుతుంది), (d) ద్రవ్యవేగం (momentum). ద్రవ్యరాశి, వడి (speed) మారవు","2) (i), (ii), (iii) మూడు సందర్భాల్లోనూ రాడ్ AB పై బలం పెరిగి స్థానభ్రంశం పెరుగుతుంది","3) (d) పైకి (upward) – ఫ్లెమింగ్ ఎడమచేతి నియమం: ధనావేశ కణం దిశ = ప్రవాహం (పశ్చిమం), బలం ఉత్తరం → క్షేత్రం పైకి"]],["పాఠంలోని ప్రశ్నలు 4 (పుట 304)",["1) ఫ్యూజ్ (లేదా MCB) మరియు ఎర్తింగ్ (భూ సంధానం)","2) I = P/V = 2000/220 ≈ 9.1 A. వలయం రేటింగ్ 5 A కంటే ఎక్కువ – అధిక ఉష్ణం, ఫ్యూజ్ కరిగి వలయం తెగిపోతుంది (ఫ్యూజ్ లేకపోతే తీగలు వేడెక్కి అగ్ని ప్రమాదం)","3) ఒకే సాకెట్‌కు ఎక్కువ ఉపకరణాలు కలపకూడదు; ఎక్కువ సామర్థ్య ఉపకరణాలు ఒకేసారి వాడకూడదు; సరైన రేటింగ్ ఫ్యూజ్/MCB వాడాలి; పాడైన తీగలు మార్చాలి"]],["అభ్యాసాలు – Exercises (పుట 308)",["1) (d) క్షేత్రం తీగ కేంద్రంగా గల ఏకకేంద్ర వృత్తాలు","2) (c) అతిగా పెరుగుతుంది","3) (a) ఒప్పు (b) తప్పు – ఆకుపచ్చ తీగ ఎర్త్; లైవ్ తీగ ఎరుపు","4) (i) శాశ్వత అయస్కాంతం (దండాయస్కాంతం) (ii) విద్యుత్ ప్రవహించే వాహకం/సోలినాయిడ్ (విద్యుదయస్కాంతం)","5) ప్రవాహ దిశ అయస్కాంత క్షేత్రానికి లంబంగా ఉన్నప్పుడు బలం గరిష్ఠం","6) ఎలక్ట్రాన్ పుంజం ముందుకు → సాంప్రదాయ ప్రవాహం వెనుక వైపు (ముందు గోడ నుండి వెనుక గోడకు). బలం కుడివైపు. ఫ్లెమింగ్ ఎడమచేతి నియమం ప్రకారం క్షేత్రం నిలువుగా కిందికి","7) (i) కుడిచేతి బొటనవేలు నియమం (ii) ఫ్లెమింగ్ ఎడమచేతి నియమం (iii) ఫ్లెమింగ్ కుడిచేతి నియమం","8) లైవ్ తీగ, న్యూట్రల్ తీగ నేరుగా తాకినప్పుడు (ఇన్సులేషన్ దెబ్బతినడం, ఉపకరణం లోపం) – వలయ నిరోధం దాదాపు సున్నా, ప్రవాహం అతిగా పెరుగుతుంది","9) ఎర్త్ తీగ లోహ ఉపకరణం బయటి కవచాన్ని భూమికి కలుపుతుంది – తక్కువ నిరోధ మార్గం. ఉపకరణంలో లీకేజ్ ఉంటే ప్రవాహం భూమిలోకి వెళ్తుంది; బయటి లోహ భాగం పొటెన్షియల్ భూమితో సమానంగా ఉంటుంది – తాకిన వ్యక్తికి తీవ్ర షాక్ తగలదు. కాబట్టి ఇస్త్రీ పెట్టె, టోస్టర్, ఫ్రిజ్ వంటి లోహ ఉపకరణాలను ఎర్త్ చేయాలి"]]],"by":"భౌతిక శాస్త్రం 10వ తరగతి (పుటలు 284–311)"}];
